const CHAPTERS: VizChapter[] = [{"id":"py-ch01","subj":"python","title":"语法与数据类型：变量/流程控制/字符串/列表/字典/元组/集合/推导式","summary":"Python 动态类型与变量语义；条件/循环流程控制；不可变字符串与切片；可变容器 list/dict/tuple/set；列表推导式；基础可运行示例。","concepts":[{"id":"py-ch01/01-variables-and-dynamic-typing","file":"01-variables-and-dynamic-typing.md","title":"01 · 变量与动态类型","kind":"compare","secs":[{"h":"一、名字与对象：绑定而不是装箱","s":"a = a + 1 做了三件事：读出 a 指向的对象、计算 a + 1 得到新对象、把 a 重新绑定到新对象。原来的对象 1 仍然被 b 指着，所以不被回收。","c":{"lang":"python","code":"a = 1        # a 绑定到整数对象 1\nb = a        # b 也绑定到同一个对象\na = a + 1    # 重新绑定 a 到新对象 2，b 不受影响\nprint(a, b)  # 2 1"}},{"h":"二、可变与不可变：唯一需要背的分类","s":"不可变对象的所有\"修改\"操作，实际都是创建新对象 + 重新绑定：","c":{"lang":"python","code":"s = \"abc\"\ns2 = s\ns += \"d\"        # 创建新字符串 \"abcd\"，s 重新绑定\nprint(s2)       # \"abc\" —— 原对象没变"}},{"h":"三、is 与 ==：身份 vs 值","s":"三个\"看起来能用\"的例外，全部不可依赖：","c":{"lang":"python","code":"a = [1, 2]\nb = [1, 2]\na == b      # True（值相同）\na is b      # False（不同对象）\n\nc = a\na is c      # True（同一对象）"}},{"h":"四、作用域：LEGB 与 global / nonlocal","s":"名字查找顺序是 Local → Enclosing → Global → Built-in。赋值语句会让名字默认成为局部变量，这导致一个经典困惑：","c":{"lang":"python","code":"count = 0\ndef inc():\n    count += 1     # UnboundLocalError：因为有赋值，count 被视为局部变量"}},{"h":"五、类型注解：提示，不强制","s":"注解在运行期只是 __annotations__ 里的字典，解释器不校验。要做运行时校验得用 pydantic、beartype、typeguard 等库；要做静态检查用 mypy / pyright。注解的价值在于工具链与可读性，而不…","c":{"lang":"python","code":"def greet(name: str) -> str:\n    return \"Hi \" + name\n\ngreet(42)      # 运行期不报错（会在拼接时因类型不符而 TypeError，但不是注解拦下的）"}},{"h":"六、边界与陷阱","s":"","c":null},{"h":"七、可运行示例：别名、缓存与浅拷贝","s":"shallow 与 deep 的对比是本章的核心：浅拷贝只复制了\"外层列表的指针数组\"，内层列表还是同一批对象。","c":{"lang":"python","code":"import copy\nimport sys\n\na = [1, 2]\nb = a\nb.append(3)\nprint(\"alias:\", a, b, a is b)          # [1,2,3] [1,2,3] True\n\nx = 256\n…"}}]},{"id":"py-ch01/02-control-flow","file":"02-control-flow.md","title":"02 · 流程控制","kind":"timeline","secs":[{"h":"一、if 与真值：一切皆可判真假","s":"条件不必是 bool，任何对象都能转换真假值：","c":{"lang":"python","code":"if []:                 # False，不进入\n    ...\nif [0]:                # True —— 非空列表就是真，哪怕内容是 0\n    ..."}},{"h":"二、for 的本质：迭代器协议","s":"等价于：","c":{"lang":"python","code":"for x in obj:\n    body(x)"}},{"h":"三、range 是惰性序列","s":"range(start, stop, step) 左闭右开，且不占内存：","c":{"lang":"python","code":"range(5)            # 0,1,2,3,4\nrange(2, 10, 3)     # 2,5,8\nrange(10**9)        # 瞬间创建，不分配 10 亿个整数\nlen(range(10**9))   # 10**9 —— O(1)，靠算术而不是计数"}},{"h":"四、for ... else：容易被误读的语法","s":"else 子句在循环未被 break 打断时执行，也就是\"跑完了\"或\"条件自然结束\"：","c":{"lang":"python","code":"for x in xs:\n    if x == target:\n        print(\"found\")\n        break\nelse:\n    print(\"not found\")     # 只有没 break 才走到这里"}},{"h":"五、while 与\"循环中修改容器\"","s":"在 for x in xs 里改 xs 结构会出问题：列表迭代器按索引走，删除元素会让后续元素前移，于是跳过一个；字典/集合会直接抛 RuntimeError: dictionary changed size during iterat…","c":{"lang":"python","code":"i = 0\nwhile i < len(xs):\n    if bad(xs[i]):\n        xs.pop(i)      # 删除后索引不前进，否则跳过下一个\n        continue\n    i += 1"}},{"h":"六、break / continue / return 的边界","s":"","c":null},{"h":"七、边界与陷阱","s":"","c":null},{"h":"八、可运行示例：协议、else 与容器修改","s":"rest 与 re-iterable 两行是\"迭代器一次性\"的实证：list(it) 消费完 it，再调 list(it) 就是空列表。","c":{"lang":"python","code":"xs = [1, 2, 3, 4]\n\nit = iter(xs)\nprint(\"next:\", next(it), next(it))          # 1 2\nprint(\"rest:\", list(it))                    # [3, 4]（迭代器已前进，不回头）\nprint(\"re-iterable:\", list(it))             # []（迭代器耗尽）\n\nfor x in xs:\n    if x == 3:\n…"}}]},{"id":"py-ch01/03-collections-and-comprehensions","file":"03-collections-and-comprehensions.md","title":"03 · 内建容器与推导式","kind":"flow","secs":[{"h":"一、复杂度速查","s":"这张表解释了最常见的性能问题：if x in list 写在循环里就是 O(n²)。判断\"在不在\"用 set。","c":null},{"h":"二、list：动态指针数组","s":"list 底层是一维的 PyObject 数组（不是链表），因此：","c":{"lang":"text","code":"list 的内存结构（ob_item 数组）\n\n  list ─► [ size=3 | allocated=4 ]\n              │\n              ▼\n         ┌────┬────┬────┬────┐\n         │ *  │ *  │ *  │ 空 │   元素是指针，指向真正的对象\n         └─┼──┴─┼──┴─┼──┴────┘\n           ▼    ▼    ▼\n…"}},{"h":"三、tuple：不只是\"不可变的列表\"","s":"tuple 的两个额外能力来自不可变性：","c":{"lang":"python","code":"point = (3, 4)\ncache = {point: \"origin-ish\"}     # tuple 当键\nx, y = point                      # 解包"}},{"h":"四、dict：哈希表，且保证插入顺序","s":"三条机制性事实：","c":{"lang":"python","code":"d = {\"a\": 1, \"b\": 2}\nd[\"c\"] = 3            # 插入\nd.get(\"z\")            # None，不抛异常\nd.get(\"z\", 0)         # 默认值\nd.setdefault(\"a\", 99) # 键存在则返回原值，不存在则插入\n\"a\" in d              # O(1) 判断键\nd.keys() / d.values() / d.items()"}},{"h":"五、set：哈希集合与集合运算","s":"set 无序、元素必须可哈希、支持 O(1) 成员判断。要去重又保序，用 dict.fromkeys(seq)（3.7+ 保序）：","c":{"lang":"python","code":"a = {1, 2, 3}\nb = {3, 4}\na | b     # 并集 {1,2,3,4}\na & b     # 交集 {3}\na - b     # 差集 {1,2}\na ^ b     # 对称差 {1,2,4}\na <= b    # 子集判断"}},{"h":"六、推导式：快，但要克制","s":"不是\"语法糖\"层面的优化，而是字节码层面的：推导式被编译成独立代码对象，在循环内直接用 LIST_APPEND 指令追加，省掉了每次迭代的 LOAD_METHOD/CALL（属性查找 + 函数调用）。实测通常快 20~40%。","c":{"lang":"python","code":"sq = [x * x for x in range(1, 4)]           # 列表推导\nevens = {x for x in range(10) if x % 2 == 0} # 集合推导\npairs = {k: v for k, v in zip(\"ab\", [1, 2])} # 字典推导\ngen = (x * x for x in range(10**6))          # 生成器表达式，惰性"}},{"h":"七、边界与陷阱","s":"","c":null},{"h":"八、可运行示例：哈希、保序与复杂度差异","s":"最后一行是\"元组不可变是浅的\"实证：元组本身没变（还是那两个引用），但它指向的列表被改了。","c":{"lang":"python","code":"from collections import Counter, defaultdict\n\nxs = [3, 1, 3, 2]\nprint(\"uniq_ordered:\", list(dict.fromkeys(xs)))     # [3, 1, 2] 去重且保序\nprint(\"set:\", sorted(set(xs)))                      # [1, 2, 3]\n\nd = {\"b\": 2, \"a\": 1}\nd[\"c\"] = 3\nprint(\"insert_order:\", list(d))                     # ['b', 'a', 'c'] 插入顺序\n…"}}]},{"id":"py-ch01/04-foundations-practical-recipes","file":"04-foundations-practical-recipes.md","title":"凯喵实战手记：Python 基础里那些「看起来会、一写就翻车」的现场","kind":"flow","secs":[{"h":"1. 动态类型不是「不用声明」，是「运行到才认类型」","s":"凯喵刚学 Python 时写过这样一个函数，以为和 Java 一样安全：","c":{"lang":"python","code":"def add(a, b):\n    return a + b\n\nadd(1, 2)        # 3\nadd(\"a\", \"b\")    # \"ab\"\nadd(1, \"b\")      # TypeError"}},{"h":"2. 可变默认参数的「共享幽灵」","s":"这是 Python 面试和线上事故第一名。凯喵曾在一次批量任务里，所有用户共享了同一份配置列表：","c":{"lang":"python","code":"def load_user(name, tags=[]):\n    tags.append(name)\n    return tags\n\nload_user(\"alice\")   # ['alice']\nload_user(\"bob\")     # ['alice', 'bob']  ← 不是你想要的！"}},{"h":"3. 闭包捕获的是变量，不是那一刻的值","s":"凯喵写循环注册回调时，九次得到同一个结果：","c":{"lang":"python","code":"callbacks = []\nfor i in range(3):\n    callbacks.append(lambda: i)\n[cb() for cb in callbacks]   # [2, 2, 2]，不是 [0, 1, 2]"}},{"h":"4. == 和 is 的边界：小整数池与驻留","s":"凯喵第一次看到下面这段，以为 Python 有 bug：","c":{"lang":"python","code":"a = 256; b = 256\na is b        # True\nx = 257; y = 257\nx is y        # False（CPython 实现相关，别依赖）"}},{"h":"5. 深浅拷贝：你改的到底是「同一份」还是「副本」","s":"凯喵做配置合并时，改了副本却影响了原配置：","c":{"lang":"python","code":"import copy\na = {\"cfg\": [1, 2, 3]}\nb = a.copy()            # 浅拷贝：顶层是新的，但嵌套列表还是同一份\nb[\"cfg\"].append(4)\na[\"cfg\"]                # [1, 2, 3, 4] ← 被改到了\nc = copy.deepcopy(a)    # 深拷贝：连嵌套也新建"}},{"h":"6. 可变对象不能当字典键","s":"凯喵用列表当缓存键，直接报错：","c":{"lang":"python","code":"cache = {}\ncache[[1, 2]] = \"x\"    # TypeError: unhashable type: 'list'"}},{"h":"7. for...else 不是「如果没进循环」而是「循环没 break」","s":"凯喵找元素时写过反逻辑：","c":{"lang":"python","code":"for item in items:\n    if item.ok:\n        break\nelse:\n    print(\"没找到\")   # 只有「一次都没 break」才执行"}},{"h":"8. 生成器一次遍历即耗尽","s":"凯喵把生成器当列表反复用，第二次全空：","c":{"lang":"python","code":"g = (x*x for x in range(3))\nlist(g)   # [0, 1, 4]\nlist(g)   # []  ← 已经消费完了"}},{"h":"9. 解包与 ：多余元素去哪了","s":"凯喵解析日志行时靠解包省了不少代码：","c":{"lang":"python","code":"first, *middle, last = [1, 2, 3, 4, 5]\n# first=1, middle=[2,3,4], last=5"}},{"h":"10. 字符串是不可变的，拼接要算代价","s":"凯喵早年用 += 在循环里拼十万行日志，慢到怀疑人生：","c":{"lang":"python","code":"s = \"\"\nfor line in big:\n    s += line        # 每次都新建字符串对象，O(n²)\n# 正确：parts = []; parts.append(line); \"\".join(parts)"}},{"h":"11. del 只是解绑，不保证立刻回收","s":"凯喵以为 del obj 会马上释放内存：","c":{"lang":"python","code":"del big_list\n# 只是把名字 big_list 从命名空间移除；若还有别的引用，对象不会回收"}},{"h":"12. 异常不是流程控制，但别裸 except:","s":"凯喵见过最危险的代码是：","c":{"lang":"python","code":"try:\n    do()\nexcept:          # 吃掉一切，包括 KeyboardInterrupt、SystemExit\n    pass"}},{"h":"凯喵复盘：把 12 个现场连成一条直觉","s":"这 12 个坑表面零散，其实有一条主线：Python 把「类型安全」和「生命周期」的责任从编译器手里交还给了你。动态类型意味着类型错误推迟到运行时；可变默认参数和闭包捕获变量，是因为「对象身份」比「名字」更根本；浅拷贝、+=、生成器耗尽…","c":null},{"h":"🧑‍💻 程序员视角","s":"def f(x, lst=[]) 的默认参数只在函数定义时求值一次，所有调用共享同一个列表——追加的元素会一直累积，正确写法是 lst=None 再在函数内初始化。闭包捕获的是「变量」而非「当时的值」，循环里创建的多个 lambda 最…","c":null},{"h":"🎓 博士生视角","s":"Python 的对象模型是「名字绑定到对象」：变量不是盒子而是标签，赋值只是重新绑定。这解释了「可变默认参数共享」（默认值对象在 __defaults__ 里只创建一次）、「闭包延迟绑定」（闭包捕获的是单元格 cell 而非快照）、「函…","c":null},{"h":"📚 考研者视角","s":"Python 面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"关于 Python 变量语义，正确的是","stem":"选择正确的描述。","opts":[{"k":"A","t":"变量在赋值前必须声明类型"},{"k":"B","t":"变量是名字，绑定到对象；对象分可变/不可变"},{"k":"C","t":"列表是可哈希的，可作为 dict 的键"},{"k":"D","t":"a=1; b=a; a=a+1 之后 b 变成 2"}],"ans":"B","why":"Python 动态类型，变量只是名字；列表不可哈希；不可变对象重新绑定不影响原绑定。"},{"kind":"fix_error","q":"修复可变默认参数陷阱","stem":"以下函数多次调用会共享同一列表，请修复（要求每次调用得到独立的新列表）： python def collect(x, buf=[]): buf.append(x) return buf","opts":[],"ans":"def collect(x, buf=None): if buf is None: buf = [] buf.append(x) return buf","why":"默认参数在定义期只创建一次，用 None 哨兵惰性初始化。"},{"kind":"output","q":"读代码写输出","stem":"python s = 'hello' print(s[1:4]) print(s[::-1]) nums = [3, 1, 2] print(sorted(nums))","opts":[],"ans":"ell olleh [1, 2, 3]","why":"切片左闭右开；[::-1] 为反转；sorted 返回新列表且升序。"},{"kind":"coding","q":"实现字符串反转函数","stem":"实现 def reverse_str(s: str) -> str:，返回反转后的字符串。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行字符串 s（可能含空格，不含换行）。 输出：反转后的字符串，占一行。","opts":[],"ans":"import sys def reverse_str(s): return s[::-1] if __name__ == '__main__': s = sys.stdin.readline().rstrip('\\n') print(reverse_str(s))","why":"切步长 -1 即可反转；也可手写 for 拼装。"},{"kind":"coding","q":"LeetCode 704 · 二分查找（Python）","stem":"实现函数 def binary_search(nums, target):，在升序整型列表中二分查找 target，返回下标，未找到返回 -1。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：第一行两个整数 n target；第二行 n 个严格升序整数（空格分隔）。 输出：target 的下标，未找到输出 -1。","opts":[],"ans":"import sys def binary_search(nums, target): lo, hi = 0, len(nums) - 1 while lo <= hi: mid = (lo + hi) // 2 if nums[mid] == target: return mid elif nums[mid] < t…","why":"经典二分，注意区间闭合与 mid 下取整；本题仅映射真题，题面以来源链接为准。"},{"kind":"coding","q":"牛客 BM21 · 旋转数组（Python）","stem":"实现函数 def rotate(nums, k):，将整型列表向右旋转 k 位（原地修改优先，也可返回新列表）。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：第一行两个整数 n k；第二行 n 个整数（空格分隔）。 输出：向右旋转 k 位后的数组，空格分隔，占一行。","opts":[],"ans":"import sys def rotate(nums, k): n = len(nums) if n == 0: return nums k %= n return nums[-k:] + nums[:-k] if k else nums if __name__ == '__main__': data = sys.st…","why":"右旋 k 位等价于取末尾 k 个移到前面；本题仅映射真题，题面以来源链接为准。"}],"works":[{"h":"可变默认参数陷阱","d":"def f(x=[]): x.append(1); return x 的默认值在定义期只创建一次，多次调用共享同一列表。正确写法：def f(x=None): x = x or []。"},{"h":"is 与 == 混用","d":"is 比较对象身份，== 比较值。a = [1]; b = [1]; a == b 为 True，a is b 为 False。比较值用 ==。"},{"h":"遍历中修改列表","d":"for x in xs: xs.remove(x) 会跳过元素或越界。正确做法：遍历副本 for x in xs[:] 或列表推导生成新列表。"},{"h":"浅拷贝误当深拷贝","d":"ys = xs.copy() 只复制外层，嵌套列表仍共享。需要 import copy; copy.deepcopy(xs)。"},{"h":"整数缓存区间","d":"-5~256 的小整数会被复用，a = 256; b = 256; a is b 可能为 True，但 257 不一定。永远用 == 比较值，不要依赖 is。"},{"h":"range 左闭右开","d":"range(3) 是 0,1,2 不含 3；想包含末尾须 range(0, n+1)，常因差一错误（off-by-one）踩坑。"},{"h":"if x: 当 is not None 用","d":"x = 0、x = \"\"、x = [] 都会被判为假，逻辑分支走错。判断\"缺失\"必须写 if x is None:。"},{"h":"xs.sort() 返回 None","d":"ys = xs.sort() 会让 ys 变成 None（原地排序无返回值）。要新列表用 ys = sorted(xs)。"}],"asks":[{"q":"Python 的变量赋值是值传递还是引用传递？可变/不可变对象在传参时表现有何不同？","a":"Python 只有对象引用传递（传对象引用，不是传值也不是 C++ 那种引用）。函数内对不可变对象（int/str/tuple）赋值会重新绑定局部名字，不影响外部；对可变对象（list/dict/set）原地修改（append、[k]=v）会影响外部，因为共享同一对象。想避免副作用，传入前 copy 或 deepcopy。","fu":["如何安全地在函数里修改调用方的列表？","深拷贝和浅拷贝的区别？"],"tag":"通用/字节"},{"q":"is 和 == 有什么区别？为什么 a=256; b=256; a is b 可能是 True，而 257 未必？","a":"== 比较值（调用 __eq__），is 比较对象身份（id 是否相同）。小整数 -5~256 在 CPython 启动时被缓存复用，所以两个 256 字面量可能指向同一对象；大整数每次新建，is 为 False。结论：比较值永远用 ==，不要用 is 比数值。","fu":["字符串字面量也会有类似缓存吗（intern）？","为什么容器间比较要用 == 而不用 is？"],"tag":"通用/腾讯"},{"q":"什么是可变默认参数陷阱？怎么写才正确？","a":"默认参数 def f(x=[]) 的 [] 在函数定义时只创建一次，所有调用共享同一列表，多次调用会累积数据。正确写法用 None 哨兵：def f(x=None): x = x or []（或 if x is None: x = []），每次调用惰性新建列表。这是面试高频题，也能延伸到默认参数求值时机。","fu":["默认参数在什么时机求值？","除了 list，dict/set 默认参数有同样问题吗？"],"tag":"通用/美团"},{"q":"列表推导式相比 for + append 好在哪儿？有没有不适合用的场景？","a":"推导式更短、可读性高、且由解释器优化（避免反复查找 append 属性）。不适合的场景：逻辑复杂需要多条语句/分支、带副作用（打印、IO）、或嵌套过深（可读性下降）。此时应改用普通 for 或拆成函数。注意 [] 会一次性生成全部元素，大数据用生成器 () 省内存。","fu":["生成器表达式和列表推导式的内存差异？","字典/集合推导式怎么写？"],"tag":"通用"}]},{"id":"py-ch02","subj":"python","title":"函数与作用域：def、参数解包、lambda、闭包、命名空间","summary":"函数定义与参数解包（args/kwargs、序列/字典解包传入）；LEGB 作用域链与命名空间；lambda 表达式与一等公民函数；闭包的自由变量绑定与延迟绑定陷阱；global/nonlocal；可变默认参数陷阱；装饰器原理（基于闭包）…","concepts":[{"id":"py-ch02/01-object-model-and-namespaces","file":"01-object-model-and-namespaces.md","title":"01 · 对象模型与命名空间：从 CPython 视角看\"变量\"","kind":"stack","secs":[{"h":"一、理论根基：一切皆对象与名字绑定","s":"（博士视角）Python 是\"一切皆对象\"的纯面向对象语言：整型、函数、类、模块、甚至代码块都是 PyObject。变量不是\"盒子\"，而是名字到对象的绑定（binding）——赋值把名字\"贴\"到对象上，而非把值搬进存储位置。这与 C++…","c":{"lang":"python","code":"a = 1        # a 绑定到小整数对象 1（CPython 对 -5~256 整数池 intern）\nb = a        # b 绑定到同一个对象，对象 ob_refcnt 加 1\na = a + 1    # 创建新对象 2，a 重新绑定；b 仍指向 1\nprint(a, b)  # 2 1"}},{"h":"二、实现机制：CPython 的对象头与引用计数","s":"每个对象在 C 层是 PyObject（变长对象为 PyVarObject）：","c":{"lang":"c","code":"struct _object { PyObject_HEAD; ... };\n/* PyObject_HEAD 展开为:\n   struct _typeobject *ob_type;   // 类型指针\n   Py_ssize_t ob_refcnt;          // 引用计数\n*/"}},{"h":"三、命名空间与作用域（LEGB）","s":"（程序员视角）名字存在于命名空间——本质就是 dict（func.__globals__、locals()、type(obj).__dict__）。查找顺序 LEGB：","c":null},{"h":"四、工程实践与对比","s":"","c":null},{"h":"五、可运行代码","s":"见 examples/ex04-LEGB.json（LEGB 查找）、examples/ex08-global-statement.json（global 改写）。","c":null}]},{"id":"py-ch02/02-function-definition-and-args","file":"02-function-definition-and-args.md","title":"02 · 函数定义与参数：def、解包与调用约定","kind":"compare","secs":[{"h":"一、理论根基：函数是一等对象、被延迟创建","s":"def 在运行期执行：它创建函数对象（<class 'function'>），把编译好的字节码、默认参数值、闭包单元（__closure__）打包，并把名字绑定到当前命名空间。因此默认参数在 def 语句执行时求值一次（见第 5 讲陷阱…","c":null},{"h":"二、实现机制：参数如何传递与解包","s":"CPython 调用约定：","c":null},{"h":"三、与 C++/Java 对比","s":"","c":null},{"h":"四、工程实践","s":"","c":null},{"h":"五、可运行代码","s":"见 examples/ex01-function-params.json、examples/ex02-argument-unpacking.json。","c":{"lang":"python","code":"def f(a, b=2, *args, c, d=4, **kw):\n    return a, b, args, c, d, kw\n\nprint(f(1, 3, 5, 7, c=9, x=0))\n# (1, 3, (5, 7), 9, 4, {'x': 0})   ← a b *args / c d **kw 各就各位\n\ndef bad(x, acc=[]):          # ✗ 默认值在 def 执行时创建一次，被所有调用共享\n    acc.append(x)\n    return acc\n…"}}]},{"id":"py-ch02/03-lambda-and-first-class","file":"03-lambda-and-first-class.md","title":"03 · lambda 与一等公民函数","kind":"compare","secs":[{"h":"一、理论根基：函数作为值","s":"一等公民（first-class）意味着函数与其它值（int、对象）地位相同：能赋给变量、作参数、作返回值、存容器。高阶函数（map/filter/sorted(key=)）依赖此特性。","c":null},{"h":"二、实现机制：lambda 是匿名函数对象","s":"lambda x: x2 编译为与 def 相同的 <function> 对象，只是没有名字、只能有一个表达式体（结果即该表达式的值）。它同样有 __globals__、__code__，可被 dis 反汇编。单一表达式限制是语法层而非…","c":null},{"h":"三、对比 C++/Java 的 lambda","s":"","c":null},{"h":"四、工程实践","s":"","c":null},{"h":"五、可运行代码","s":"见 examples/ex03-lambda-basic.json、examples/ex09-first-class-function.json。","c":null}]},{"id":"py-ch02/04-closure","file":"04-closure.md","title":"04 · 闭包：自由变量绑定、延迟绑定与 nonlocal","kind":"compare","secs":[{"h":"一、理论根基：函数是携带环境的对象","s":"闭包 = 函数 + 其定义时所处的词法环境（外层作用域变量）。当内层函数引用了外层函数的局部变量（自由变量 free variable），这些变量不能被回收，被\"冻结\"进函数的 __closure__（一组 cell 对象）。这是函数式…","c":null},{"h":"二、实现机制：cell 与 __closure__","s":"CPython 用 cell 对象持有自由变量：inner.__closure__ 是 cell 元组，每个 cell.cell_contents 是被捕获的变量。外层变量被改写为\"通过 cell 间接访问\"，即使外层函数已返回，cel…","c":null},{"h":"三、对比","s":"","c":null},{"h":"四、工程实践","s":"","c":null},{"h":"五、可运行代码","s":"见 examples/ex05-closure-counter.json、examples/ex06-closure-late-binding.json、examples/ex11-closure-cache.json。","c":{"lang":"python","code":"def counter():\n    n = 0\n    def inc():\n        nonlocal n            # 去掉这行会 UnboundLocalError：赋值使 n 成为局部名\n        n += 1\n        return n\n    return inc\n\nc = counter()\n…"}}]},{"id":"py-ch02/05-mutable-default-and-decorator","file":"05-mutable-default-and-decorator.md","title":"05 · 可变默认参数陷阱与装饰器原理","kind":"compare","secs":[{"h":"一、可变默认参数陷阱（坑源）","s":"默认参数在 def 执行时求值并绑定一次，之后所有调用共享同一个默认对象。若默认值是可变对象（list/dict/set），def f(x=[]): x.append(1) 会让多次调用共享同一列表 → 累积污染。","c":null},{"h":"二、装饰器原理（基于闭包）","s":"@trace 等价于 f = trace(f)：装饰器是接收函数、返回函数的高阶函数，利用闭包包装原函数，在不改源码的前提下加日志/计时/缓存/权限。原理依赖：① 函数是一等对象；② 闭包持有被包装函数；③ args/kwargs 透传…","c":{"lang":"python","code":"def trace(fn):\n    def wrapper(*args, **kwargs):\n        print(\"call\", fn.__name__)\n        return fn(*args, **kwargs)\n    return wrapper"}},{"h":"三、对比","s":"","c":null},{"h":"四、工程实践","s":"","c":null},{"h":"五、可运行代码","s":"见 examples/ex07-mutable-default-arg.json、examples/ex10-decorator-basic.json、examples/ex12-default-arg-None.json。","c":null}]},{"id":"py-ch02/06-object-practical-recipes","file":"06-object-practical-recipes.md","title":"凯喵实战手记 · Python 对象模型与函数式的「当场翻车」","kind":"flow","secs":[{"h":"现场 1：可变默认参数是共享的陷阱","s":"默认参数在函数定义时只创建一次，所有调用共享同一个列表。凯喵的修法：默认用 None，函数体内 lst = lst or []，每次调用拿到新列表。","c":{"lang":"python","code":"def add_item(x, lst=[]):\n    lst.append(x)\n    return lst\n\nprint(add_item(1))  # [1]\nprint(add_item(2))  # [1, 2]  —— 不是你以为的 [2]！"}},{"h":"现场 2：闭包延迟绑定（late binding）","s":"闭包捕获的是变量名 i 本身，循环结束后 i 是 2，所以全部返回 2。凯喵：要「快照」当前值就 lambda i=i: i，把当前值绑定成默认参数。","c":{"lang":"python","code":"funcs = [lambda: i for i in range(3)]\nprint([f() for f in funcs])  # [2, 2, 2]，不是 [0, 1, 2]"}},{"h":"现场 3：UnboundLocalError 的编译期决定","s":"只要函数体内有 x = 20 这种赋值，Python 就把 x 当成局部变量，而 print(x) 在赋值前执行就报错。凯喵：要改全局用 global x；嵌套里改外层用 nonlocal x，别以为「能读到就是全局」。","c":{"lang":"python","code":"x = 10\ndef f():\n    print(x)   # UnboundLocalError!\n    x = 20"}},{"h":"现场 4：装饰器丢元信息","s":"装饰后的函数变成了 wrapper，名字、文档、注解全丢。凯喵：用 functools.wraps(f) 装饰 wrapper，元信息自动保留，调试和文档才正确。","c":{"lang":"python","code":"def deco(f):\n    def wrapper(*a, **k):\n        return f(*a, **k)\n    return wrapper\n\n@deco\ndef greet(): \"\"\"say hi\"\"\"\nprint(greet.__name__)  # 'wrapper'，不是 'greet'"}},{"h":"现场 5：参数顺序的硬规则","s":"调用时顺序必须是：位置 → 默认 → args → 仅关键字 → kwargs。写函数时签名顺序也一样。凯喵：想强制调用方用关键字传参，把参数放 之后（如 def f(a, , b)），可读性更好也避免位置错传。","c":null},{"h":"现场 6：args / kwargs 解包重复键","s":"解包时后者覆盖前者，不会报错。凯喵：动态拼参数字典时警惕重复键静默覆盖，那是隐蔽 Bug 的来源。","c":{"lang":"python","code":"def f(a, b): ...\nf(**{'a':1}, **{'a':2, 'b':3})  # 后面的 'a' 覆盖前面的，实际 a=2"}},{"h":"现场 7：函数属性当「静态变量」却忘了全局共享","s":"函数对象本身是可变对象，挂属性确实能当静态变量，但它是全局共享的，并发/多实例下会互相污染。凯喵：需要状态优先用类或闭包变量，别滥用函数属性当存储。","c":{"lang":"python","code":"def counter():\n    counter.n = getattr(counter, 'n', 0) + 1\n    return counter.n"}},{"h":"现场 8：把函数属性当\"静态变量\"却忘了它是全局共享","s":"（与上呼应）凯喵强调：函数属性本质上挂在模块级对象上，任何地方调用都改同一份。需要隔离状态时，用实例属性或闭包，别图省事挂函数上。","c":null},{"h":"现场 9：误以为 del/重新赋值能改外部可变对象","s":"lst = ... 只改局部绑定，不影响调用方；要改原对象内容得用切片赋值或 clear()+extend()。凯喵：分清「重绑定名字」和「原地修改对象」。","c":{"lang":"python","code":"def f(lst):\n    lst = [1, 2, 3]   # 只是把局部名 lst 指向新列表，外部没变\ndef g(lst):\n    lst[:] = [1, 2, 3]  # 改的是原列表内容，外部变了"}},{"h":"现场 10：命名空间与作用域 LEGB","s":"Python 查找名字顺序：Local → Enclosing → Global → Builtin。凯喵：遇到「明明定义了却报 NameError」，先想它在哪个作用域、是否被内层同名遮蔽、是否在引用前执行到。","c":null},{"h":"现场 11：可变对象作类属性的共享灾难","s":"类属性是共享的，想每个实例独立就在 __init__ 里 self.items = []。凯喵：可变类属性是经典坑，初始化放实例里。","c":{"lang":"python","code":"class Box:\n    items = []   # 类属性，所有实例共享\nb1 = Box(); b1.items.append(1)\nb2 = Box(); print(b2.items)  # [1] —— b2 也\"继承\"了这个 1"}},{"h":"现场 12：深浅拷贝的边界","s":"copy.copy 浅拷贝只复制一层，嵌套容器仍共享；copy.deepcopy 递归全拷但慢且可能递归爆栈。凯喵：需要独立副本又含嵌套时上 deepcopy，但注意对象有循环引用时 deepcopy 能处理（它带备忘录），自己写的递归…","c":null},{"h":"凯喵复盘：Python 的「坑」本质是「运行时语义和你以为的不同」","s":"这 12 个现场，没有一个是因为语法错误——它们都能跑，只是结果偏离直觉。凯喵总结它们的共同根因：Python 的很多行为是在运行时按对象模型动态决定的，而你脑子里想的是「静态/直觉版本」。比如默认参数是在函数定义时求值一次（不是每次调…","c":null},{"h":"凯喵速记：Python 的三条防坑底线","s":"只记三句也能避掉大部分灵异事件：第一，默认参数用 None、可变状态放实例，别让同一份可变对象被多处共享；第二，函数内要改外层变量就 global/nonlocal，别靠直觉猜作用域；第三，闭包要快照当前值就 lambda i=i，别等…","c":null},{"h":"🧑‍💻 程序员视角","s":"可变默认参数是共享陷阱，闭包延迟绑定是第二个——两者都源于「定义时求值一次」。UnboundLocalError 的根因是「函数内赋值让名字变成局部变量」，即使在赋值前读取也会报错，要改外部变量得声明 global/nonlocal。装…","c":null},{"h":"🎓 博士生视角","s":"Python 的函数是「一等对象」，装饰器本质是「接收函数、返回函数」的高阶函数，@deco 只是 f = deco(f) 的语法糖。functools.wraps 复制的是 __wrapped__ 与元信息，使 inspect.sig…","c":null},{"h":"📚 考研者视角","s":"Python 面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"可变默认参数的真实行为","stem":"观察下列代码，add(1) 后再 add(2) 的返回值是： python def add(x, lst=[]): lst.append(x) return lst 第二次调用 add(2) 返回什么？","opts":[{"k":"A","t":"[2]"},{"k":"B","t":"[1, 2]"},{"k":"C","t":"[]"},{"k":"D","t":"抛出 TypeError"}],"ans":"B","why":"默认参数 [] 在 def 执行时求值一次，被后续所有调用共享（存于函数对象的 __defaults__）。因此两次调用累积成 [1, 2]。正确写法用 None 哨兵惰性初始化。"},{"kind":"fix_error","q":"修复闭包延迟绑定","stem":"下列代码期望输出 [0, 1, 2]，实际输出 [2, 2, 2]。请指出根因并给出修复后的代码： python funcs = [lambda: i for i in range(3)] print([f() for f in funcs])","opts":[],"ans":"funcs = [lambda i=i: i for i in range(3)] # 用默认参数在定义时固化当前值 print([f() for f in funcs]) # [0, 1, 2] # 或用工厂函数： def make(n): return lambda: n funcs = [make(i) for…","why":"闭包捕获的是变量 i 这个 cell（自由变量按引用绑定），调用时才求值；循环结束时 i=2，所以三个 lambda 都返回 2。用默认参数 i=i 把当时的值固化到函数对象上即可。"},{"kind":"output","q":"LEGB 作用域与 global 的影响","stem":"写出下列代码的输出，并说明 x 在函数内外分别绑定于哪个作用域： python x = 10 def f(): x = 1 print('in f:', x) f() print('outer:', x) def g(): global x x = 99 g() print('after g:', x)","opts":[],"ans":"in f: 1 outer: 10 after g: 99","why":"f 内的 x = 1 使 x 成为局部变量（编译期决定），不影响模块级 x，故 outer 仍为 10。g 用 global x 声明后赋值的就是模块级名字，故 after g 为 99。作用域归属在编译期由函数体内是否出现赋值决定，可用 f.__code__.co_varnames 验证。"},{"kind":"coding","q":"实现一个保留元信息的计时装饰器","stem":"用闭包实现一个装饰器 timed： 1. 打印被装饰函数的调用耗时（用 time.perf_counter）； 2. 必须用 functools.wraps 保留原函数的 __name__ 与 __doc__； 3. 支持接收任意位置/关键字参数并返回原返回值； 4. 用它装饰一个 slow_add(a, b)（内部 time.sleep(0.01)），验证 slow_add.__name__ 仍…","opts":[],"ans":"import time from functools import wraps def timed(f): @wraps(f) def wrapper(args, kwargs): t0 = time.perf_counter() try: return f(args, kwargs) finally: print(f…","why":"装饰器本质是「接受函数返回函数」的高阶函数；@wraps 把 __name__/__doc__/__module__/__wrapped__ 从原函数复制到 wrapper，避免元信息丢失。args/kwargs 保证透传任意签名。"},{"kind":"choice","q":"关于一等公民函数，正确的是","stem":"Python 中函数是一等公民。下列说法正确的是：","opts":[{"k":"A","t":"函数只能定义在模块顶层，不能嵌套定义"},{"k":"B","t":"函数可以赋值、作为参数传入、作为返回值、存入容器"},{"k":"C","t":"lambda 可以包含多条语句和 return"},{"k":"D","t":"函数不能作为 dict 的 value"}],"ans":"B","why":"函数对象与其他对象一样可赋值、传参、返回、入容器（dict 分发是常见模式）。lambda 只能含单个表达式；函数可以嵌套（这正是闭包的基础）。"},{"kind":"coding","q":"用函数封装解决 two-sum（函数签名与高阶函数实践）","stem":"完成 LeetCode 1（two-sum）的函数封装实现：定义 def two_sum(nums, target) 返回下标列表，要求： 1. 内部用 dict 做「值→下标」映射，单次遍历 O(n)； 2. 额外提供一个高阶函数 make_checker(target)，返回一个用于判断某数是否被命中的闭包； 3. 说明为何把 target 用闭包捕获比每次传参更利于复用。 题面与示例以链接为…","opts":[],"ans":"import sys def make_checker(target): def check(seen, v): return (target - v) in seen return check def two_sum(nums, target): check = make_checker(target) seen =…","why":"哈希表单次遍历把 O(n^2) 降到 O(n)。把 target 用闭包捕获（工厂函数）可生成一批「预设条件的检查器」，避免每次调用重复传参，是高阶函数的典型收益；但要注意闭包捕获的是变量本身（见本章延迟绑定坑）。"},{"kind":"coding","q":"用函数式风格实现字符串变换（reverse-string 变体）","stem":"完成 LeetCode 344（reverse-string）的函数式实现：定义 def reverse_str(s)，要求： 1. 至少给出两种实现：切片 s[::-1] 与「首尾双指针原地交换」（字符串不可变需先转 list）； 2. 用 timeit 或 perf_counter 对比两者在 length=106 时的耗时差异； 3. 说明为何切片通常更快（C 层实现 vs Python 层…","opts":[],"ans":"def reverse_str_slice(s): return s[::-1] def reverse_str_pointers(s): a = list(s) i, j = 0, len(a) - 1 while i < j: a[i], a[j] = a[j], a[i] i += 1; j -= 1 retur…","why":"切片在 CPython 中由 C 层实现（一次拷贝），而双指针是 Python 字节码循环，解释器开销大得多。字符串不可变，原地交换必须借助 list 中转，且 join 回字符串——这也是「可变/不可变」语义对性能的直接影响。"}],"works":[{"h":"可变默认参数（最经典的坑）","d":"python def add(x, lst=[]): # 错：[] 在函数定义时创建一次，被所有调用共享 lst.append(x) return lst add(1); add(2) # [1, 2] 而不是 [2] 原理：def 语句执行时，默认参数表达式被求值并绑定到函数对象的 __defaults__（可用 add.__def…"},{"h":"闭包延迟绑定（循环里创建 lambda/函数）","d":"python funcs = [lambda: i for i in range(3)] [f() for f in funcs] # [2, 2, 2] 而不是 [0, 1, 2] 原理：闭包捕获的是变量 i 这个 cell（自由变量按引用绑定），调用时才去查值；循环结束时 i=2。 正解：用默认参数固化当时值 lambda i=i…"},{"h":"global / nonlocal 误用导致 UnboundLocalError","d":"python x = 10 def f(): print(x) # UnboundLocalError：本函数内有 x=... 赋值，x 被判为局部 x = 1 原理：作用域在编译期决定——函数体内任何位置对名字赋值，该名字在整个函数内都是局部的（存于 f.__code__.co_varnames）。 正解：要改外层用 global（…"},{"h":"lambda 里塞语句 / 多表达式","d":"lambda 主体只能是单个表达式，不能写 return、if 语句块、for 循环。 正解：用条件表达式 lambda x: x if x > 0 else -x，或改用 def。lambda 适合短小回调，超过一行就该用 def（可读性也是工程指标）。"},{"h":"参数顺序写错：SyntaxError: non-default argument follo…","d":"def f(a=1, b) 非法。顺序必须是：位置参数 → 默认参数 → args → 仅关键字（ 后）→ kwargs。 深层：这是调用侧能否无歧义匹配的语法保证；仅关键字参数（def f(a, , debug=False)）正是为了强制调用方写清 debug=。"},{"h":"装饰器丢元信息（不用 functools.wraps）","d":"python def deco(f): def wrapper(a, k): return f(a, k) return wrapper @deco def foo(): \"doc\" foo.__name__ # 'wrapper'，文档与签名丢失 后果：日志/文档工具（Sphinx）、依赖注入框架（按签名）、inspect.sign…"},{"h":"args /","d":"kwargs 解包顺序与重复键 调用时 f(a, b, c) 中多个 解包不允许重复键（TypeError: got multiple values for keyword argument）；定义时 args 之后的普通参数是仅关键字。 另外 f(a, b) 在 Python 3.5+ 才支持一次调用里多次解包。"},{"h":"把函数属性当\"静态变量\"却忘了它是全局共享","d":"def f(): f.counter = getattr(f, \"counter\", 0) + 1 能工作，但 递归/并发下不是线程安全，且测试之间互相污染。 正解：需要状态就用类、闭包工厂或 collections.Callable 对象；并发场景加锁或 threading.local。"}],"asks":[{"q":"为什么 def f(x, lst=[]) 会在多次调用间共享同一个列表？从 CPython 对象模型说明，并给出查看证据的方式。","a":"因为默认参数在 def 语句执行时求值一次，结果存进函数对象的 __defaults__（元组）。后续每次调用只是把 __defaults__ 里的那个对象绑定到形参，不会重新求值。 - 证据：f.__defaults__ 可见同一个 list 对象；id(f.__defaults__[0]) 在多次调用后不变；f.__defaults__[0] is f.__defaults__[0] 恒为 T…","fu":["如果默认值写成 def f(x, t=time.time())，时间戳会在什么时候固定？","为什么 lst or [] 与 lst if lst is not None else [] 不等价？"],"tag":"通用/字节"},{"q":"闭包捕获的是「值」还是「变量」？为什么 [lambda: i for i in range(3)] 全返回 2？如何用 __closure__ 证明？","a":"捕获的是变量本身（更准确说是 cell 对象），不是当时的值——这叫延迟绑定（late binding）。 - 机制：推导式里的 i 是同一个局部名字，三个 lambda 的自由变量都指向同一个 cell。lambda 体在调用时才去 cell 里取值，而那时循环已结束、i 停在 2。 - 证明：funcs[0].__closure__ 返回 cell 元组，funcs[0].__closure_…","fu":["为什么循环变量在 Python 里不每次迭代新建作用域？（与 for 不引入新作用域有关）","生成器表达式 (lambda: i for i in range(3)) 的行为有何不同？"],"tag":"通用/腾讯"},{"q":"装饰器 @deco 在语法层面做了什么？叠放多个装饰器时执行顺序如何？为什么必须加 functools.wraps？","a":"语法层：@deco 等价于 f = deco(f)——在 def 产生函数对象后立即把名字重新绑定到 deco 的返回值。装饰器本身是接受函数、返回函数的高阶函数。 - 叠放顺序： python @a @b def f(): ... 等价于 f = a(b(f))——离 def 最近的先执行（b 先包装 f，再由 a 包装结果）。执行顺序自下而上，调用顺序自上而下（先经过 a 再到 b）。 - w…","fu":["如何写一个既能 @deco 又能 @deco() 的装饰器？","装饰器会影响递归函数吗？（每次递归都经过 wrapper）"],"tag":"通用/字节"},{"q":"global 与 nonlocal 有何区别？为什么在函数里 print(x) 后再 x = 1 会抛 UnboundLocalError？","a":"区别：global 声明名字属于模块（全局）作用域；nonlocal 声明名字属于外层函数（闭包）作用域，且该名字必须已在外层绑定过（否则 SyntaxError）。两者都只影响「赋值绑定到哪一层」，不影响读取。 - UnboundLocalError 根因：Python 的作用域在编译期决定。只要函数体内任何位置出现对某名字的赋值（且无 global/nonlocal 声明），编译器就把它标记为…","fu":["类作用域为什么不参与 LEGB 的闭包链？（类体内定义的方法看不到类变量作为闭包）","如何用 dis 模块观察 LOAD_FAST / LOAD_GLOBAL / LOAD_DEREF 的差异？"],"tag":"通用/阿里"}]},{"id":"py-ch03","subj":"python","title":"内置数据结构：list/tuple/dict/set 与推导式、深浅拷贝","summary":"list 动态数组（扩容/切片/copy）；tuple 不可变语义与含可变元素；dict 哈希表（哈希、开放寻址、3.7+ 紧凑化与插入序）；set 集合运算；列表/字典/集合推导式；生成器表达式与惰性；浅拷贝 vs 深拷贝与对象图。CPy…","concepts":[{"id":"py-ch03/01-list-and-tuple-internals","file":"01-list-and-tuple-internals.md","title":"list 与 tuple 的底层：动态指针数组 vs 定长引用数组","kind":"compare","secs":[{"h":"1. list 不是链表，是「过度分配的动态指针数组」","s":"CPython 的 list 对象（Objects/listobject.c）结构可简化为：","c":{"lang":"c","code":"typedef struct {\n    PyObject_VAR_HEAD      // 含 ob_size（已用长度）\n    PyObject **ob_item;    // 指向「指针数组」的指针：每个槽位是一个 PyObject*\n    Py_ssize_t allocated;  // 已分配的槽位数（>= ob_size）\n} PyListObject;"}},{"h":"2. 复杂度：为什么 append 摊销 O(1)、insert(0) 是 O(n)","s":"注意一个反直觉点：list 缩容也会发生。pop 后若 ob_size 掉到 allocated/2 以下，CPython 会 realloc 缩小，避免长期持有大数组——但这会让「反复 append/pop」在临界点抖动。","c":null},{"h":"3. tuple：不可变 ≠ 内容不可变","s":"tuple 是定长的引用数组：","c":{"lang":"c","code":"typedef struct {\n    PyObject_VAR_HEAD\n    PyObject *ob_item[1];   // 定长，创建时确定，不可扩容\n} PyTupleObject;"}},{"h":"4. 与 C++ / Java 的对照（帮助建立直觉）","s":"","c":null},{"h":"5. 速记","s":"","c":null}]},{"id":"py-ch03/02-dict-and-set-hash","file":"02-dict-and-set-hash.md","title":"dict 与 set：开放寻址哈希表与可哈希契约","kind":"flow","secs":[{"h":"1. dict 是哈希表，不是树（3.7 之前也不保证顺序）","s":"CPython 的 dict（Objects/dictobject.c）用开放寻址（open addressing）而非链地址法解决冲突。3.6 起引入「紧凑化布局」，3.7 起语言规范保证插入顺序。","c":{"lang":"text","code":"indices（稀疏索引表）：  [ 2 | - | 0 | - | 1 | ... ]   # 存 entries 中的下标，- 表示空\nentries（紧凑实体表）：   [ (h0,k0,v0), (h1,k1,v1), (h2,k2,v2) ]  # 按插入顺序紧密排列"}},{"h":"2. 哈希冲突与「最坏 O(n)」","s":"","c":null},{"h":"3. 可哈希契约：__hash__ 与 __eq__ 必须一致","s":"一个对象能作为 dict 的键 / set 的元素，必须可哈希（hashable）：","c":{"lang":"python","code":"class P:\n    def __init__(self, x): self.x = x\n    def __eq__(self, o): return self.x == o.x\n    # 没有 __hash__ -> __hash__ 被置为 None\n{P(1): \"a\"}   # TypeError: unhashable type: 'P'"}},{"h":"4. set：同一套哈希机制，只存 key","s":"","c":null},{"h":"5. 工程选型表","s":"","c":null},{"h":"6. 速记","s":"","c":null}]},{"id":"py-ch03/03-comprehension-and-copy","file":"03-comprehension-and-copy.md","title":"推导式、生成器与深浅拷贝","kind":"stack","secs":[{"h":"1. 推导式（comprehension）：语法糖，但不只是糖","s":"四种推导式（外加生成器表达式）：","c":{"lang":"python","code":"[x * 2 for x in range(5)]                 # list\n{x: x ** 2 for x in range(5)}             # dict\n{x % 3 for x in range(10)}                # set\n(x * 2 for x in range(5))                 # 生成器表达式（圆括号，惰性）"}},{"h":"2. 生成器表达式 vs 列表推导式：内存与复用","s":"","c":{"lang":"python","code":"import sys\nbig_list = [x for x in range(10**6)]       # 约 8MB+（指针数组）\nbig_gen  = (x for x in range(10**6))       # 约 100 字节\nprint(sys.getsizeof(big_list), sys.getsizeof(big_gen))"}},{"h":"3. 深浅拷贝：拷贝的是\"引用\"还是\"对象图\"","s":"这是本章最容易出错、也最爱考的部分。","c":{"lang":"python","code":"b = a[:]              # 切片\nb = list(a)           # 工厂函数\nb = copy.copy(a)      # copy 模块\nb = a.copy()          # list 自带方法（3.3+）"}},{"h":"4. 共享引用的经典陷阱：[[0]] 3","s":"同理 dict.fromkeys 也有类似陷阱（默认值是共享对象）。","c":{"lang":"python","code":"a = [[0]] * 3        # 错：3 个槽位指向同一个 [0]\na[0].append(1)\nprint(a)   # [[0, 1], [0, 1], [0, 1]]   <- 三个都变了！"}},{"h":"5. == 与 is：值相等 vs 同一性","s":"","c":{"lang":"python","code":"a, b = 256, 256\nprint(a is b)   # True（小整数缓存）\na, b = 257, 257\nprint(a is b)   # False（同一行赋值可能仍 True，取决于编译器常量折叠——不要用 is 比数值！）"}},{"h":"6. 速记","s":"","c":null}]},{"id":"py-ch03/04-container-practical-recipes","file":"04-container-practical-recipes.md","title":"凯喵实战手记 · 列表、字典与集合：那些「看着能用、其实很慢」的写法","kind":"flow","secs":[{"h":"现场 1：in list 是线性扫描，in set 是哈希查找","s":"判断元素在不在，列表要逐个比较，复杂度是线性的；集合和字典靠哈希，平均是常数时间。凯喵的现场经验：在循环里对列表做成员判断，数据量一大就是从秒级掉进分钟级。需要频繁判断存在性，先转成集合。","c":{"lang":"python","code":"big = list(range(100000))\ns = set(big)\n99999 in big   # 慢：要扫到底\n99999 in s     # 快：一次哈希定位"}},{"h":"现场 2：列表的插入与删除不是免费的","s":"在列表头部插入或删除元素，后面所有元素都要整体后移，复杂度是线性的。凯喵：频繁在两端操作就用 collections.deque，它是双端队列，两端操作都是常数时间。用错容器，再怎么优化代码也救不回来。","c":null},{"h":"现场 3：字典的键必须可哈希","s":"列表、字典、集合这些可变对象不能当字典的键，因为它们的哈希会变。凯喵：需要「用一组值当键」时，转成元组；需要可变结构当键，就先序列化成不可变形式。哈希稳定性是字典正确性的地基。","c":{"lang":"python","code":"d = {}\nd[(1, 2)] = \"ok\"     # 元组可哈希\n# d[[1, 2]] = \"no\"   # 列表不可哈希，报 TypeError"}},{"h":"现场 4：自定义对象当键要实现 __hash__ 与 __eq__","s":"默认的哈希基于对象身份，两个「内容相同」的实例哈希不同，会被当成两个键。凯喵：要让内容相等的对象当同一个键，必须同时重写 __hash__ 和 __eq__，而且两者要一致——相等的对象哈希必须相等。","c":null},{"h":"现场 5：集合去重会丢掉顺序","s":"set 是无序的，用 list(set(x)) 去重后顺序不确定。凯喵：既要去重又要保序，用 dict.fromkeys(x)，它按插入顺序保留唯一元素，这是 Python 里最干净的保序去重写法。","c":{"lang":"python","code":"items = [3, 1, 3, 2, 1]\nlist(dict.fromkeys(items))   # [3, 1, 2]，保序去重"}},{"h":"现场 6：切片是浅拷贝，嵌套对象仍共享","s":"lst[:] 只复制最外层，里面的子列表还是同一份。凯喵：需要完全独立用 copy.deepcopy，只复制一层用 copy.copy 或切片。改内层影响原对象，是「明明拷贝了怎么还变」的经典来源。","c":null},{"h":"现场 7：列表推导式比循环 append 快，但不是万能","s":"推导式在 C 层执行循环，通常比手写 for 加 append 快。凯喵提醒：但推导式里塞复杂逻辑会牺牲可读性，而且它会一次性构建整个列表，数据极大时内存吃紧。需要惰性求值就换生成器表达式。","c":{"lang":"python","code":"squares = [x * x for x in range(10)]        # 一次性建列表\ngen = (x * x for x in range(10))            # 惰性生成器"}},{"h":"现场 8：sort() 原地排序返回 None","s":"list.sort() 原地改列表、返回 None；sorted() 返回新列表。凯喵见过 x = lst.sort() 得到 None 然后报错。记住：要新列表用 sorted，要原地改才用 sort，别把返回值接走。","c":null},{"h":"现场 9：排序的 key 函数只调用一次","s":"sorted 的 key 对每个元素只调用一次，比在 cmp 里反复比较高效得多。凯喵：需要多级排序时，key 返回元组即可，Python 会按元组逐项比较。用对 key，比手写比较函数又快又清晰。","c":{"lang":"python","code":"people = [(\"kai\", 3), (\"miao\", 1)]\nsorted(people, key=lambda p: (p[1], p[0]))   # 先按年龄再按名字"}},{"h":"现场 10：字典的 get 与 setdefault","s":"d.get(k, default) 取不到时返回默认值但不写入；d.setdefault(k, default) 取不到时会写入并返回默认值。凯喵：初始化分组时用 setdefault 很顺手，但要清楚它有副作用——会真的往字典里塞一个…","c":{"lang":"python","code":"groups = {}\nfor k, v in pairs:\n    groups.setdefault(k, []).append(v)"}},{"h":"现场 11：defaultdict 省掉存在性判断","s":"collections.defaultdict(list) 访问不存在的键会自动创建空列表，省掉 if k not in d。凯喵：分组、计数、图邻接表这些场景，defaultdict 能让代码干净一大截，而且比手写判断更快。","c":null},{"h":"现场 12：元组不可变，但可以包含可变对象","s":"元组本身不可变，但如果里面装了列表，那个列表还是能改。凯喵：所谓「不可变」只是元组这一层的引用不可变，深层对象该变还是变。要真正不可变，里面的元素也得是不可变类型。","c":null},{"h":"现场 13：+= 对列表是原地扩展","s":"lst += [x] 对列表是原地 extend，会修改原对象；而 lst = lst + [x] 会创建新列表。凯喵：这个区别在函数传参时尤其致命——前者影响调用方看到的列表，后者不会。分清楚，才不会「函数里改着改着外面也变了」。","c":null},{"h":"现场 14：大列表的内存与 array/numpy","s":"纯 Python 列表存的是对象指针，每个整数都是独立对象，内存开销大。凯喵：存大量同类型数值时，用 array 模块或 NumPy，内存能省一个数量级，运算也快得多。容器选型的第一步，是先想清楚「存的是什么、要做什么」。","c":null},{"h":"凯喵叮嘱：先把数据规模问清楚，再选容器","s":"最后叮嘱一句：写代码前先问自己「这份数据大概多大、我要做哪些操作」。几十条数据用列表随便玩都没事，几十万条就完全不同了——成员判断可能从线性变成哈希、队列可能从列表换成双端队列、数值存储可能从列表换成数组。凯喵带人做性能优化，第一步永远…","c":null},{"h":"🧑‍💻 程序员视角","s":"x in list 是 O(n) 线性扫描，x in set 是 O(1) 哈希查找——循环里做成员判断必须换集合。列表的 insert(0, x) 与 pop(0) 都是 O(n)，频繁头操作应该用 collections.deque…","c":null},{"h":"🎓 博士生视角","s":"Python 的 dict 是「开放寻址 + 紧凑数组」的实现（3.6+ 保留插入顺序），平均查找 O(1)、最坏 O(n)（哈希冲突）。set 与 dict 同源，只是不存值。哈希表的性能依赖「哈希函数均匀」与「负载因子」，这也是为什…","c":null},{"h":"📚 考研者视角","s":"Python 面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"[[0]] 3 的真实行为","stem":"执行 a = [[0]] 3 后，运行 a[0].append(1)，a 的值是什么？","opts":[{"k":"A","t":"[[0, 1], [0], [0]]"},{"k":"B","t":"[[0, 1], [0, 1], [0, 1]]"},{"k":"C","t":"[[0], [0], [0]]"},{"k":"D","t":"抛出 TypeError"}],"ans":"B","why":"对序列做的是重复引用：三个槽位指向同一个列表对象，改一个全都变。正确写法是 [[0] for _ in range(3)]，每次迭代新建列表。对不可变元素（如 [0]3）则无此问题。"},{"kind":"output","q":"浅拷贝与原地修改的影响","stem":"写出下列代码的输出，并解释为何 a 也被修改： python a = [[1, 2], [3, 4]] b = a[:] b[0].append(99) b[1] = [9] print(a) print(b)","opts":[],"ans":"[[1, 2, 99], [3, 4]] [[1, 2, 99], [9]]","why":"b = a[:] 是浅拷贝：只新建一层容器，槽位仍指向同一批子列表。b[0].append(99) 原地改共享的子列表，所以 a 也变；而 b[1] = [9] 是替换槽位（重新绑定 b 自己的槽），不影响 a。要完全独立需 copy.deepcopy。"},{"kind":"fix_error","q":"修复遍历中删除元素的问题","stem":"下面两段代码都有问题，请指出错误（或异常类型）并给出修复方案： python # ① 列表：看似正确实则会漏删 nums = [1, 2, 2, 3, 2] for x in nums: if x == 2: nums.remove(x) # ② 字典：直接抛异常 d = {'a': 1, 'b': 2, 'c': 3} for k in d: if d[k] < 3: del d[k]","opts":[],"ans":"# ① 用推导式重建（推荐） nums = [x for x in nums if x != 2] # ② 遍历键的快照 for k in list(d): if d[k] < 3: del d[k] # 或同样用推导式重建 d = {k: v for k, v in d.items() if v >= 3}","why":"迭代器按内部索引/表槽推进：列表删除会让后续元素前移导致漏处理；字典在迭代中改变大小直接抛 RuntimeError: dictionary changed size during iteration。修复方式是遍历副本（list(d)、d.copy()）或用推导式重建新容器。"},{"kind":"coding","q":"推导式与生成器：内存与复用对比","stem":"完成下列要求： 1. 用列表推导式生成 0~999999 的平方列表，用 sys.getsizeof 打印其占用； 2. 用生成器表达式生成同样的序列，打印 sys.getsizeof； 3. 用生成器对同一个表达式连续 sum() 两次，观察第二次结果并解释； 4. 说明何时应选生成器、何时应选列表。","opts":[],"ans":"import sys lst = [x x for x in range(106)] gen = (x x for x in range(106)) print('list bytes:', sys.getsizeof(lst)) print('gen bytes:', sys.getsizeof(gen)) g2 =…","why":"列表推导式即时构建、占用随 n 线性增长（存的是 PyObject 指针数组）；生成器只保存迭代状态，占用约百字节级别（O(1)）。但生成器是一次性的，消费完再迭代得到空。需要多次遍历或按索引访问用列表；处理大数据流、只遍历一次用生成器。"},{"kind":"choice","q":"dict 查找为何是 O(1)，且 3.7 起有序","stem":"关于 CPython 的 dict，正确的是：","opts":[{"k":"A","t":"dict 用红黑树实现，查找 O(log n)"},{"k":"B","t":"dict 用开放寻址哈希表，平均查找 O(1)，3.7 起保证插入顺序"},{"k":"C","t":"dict 的键可以是任意对象，包括 list"},{"k":"D","t":"hash() 的值跨进程稳定，可安全用于持久化分片"}],"ans":"B","why":"CPython dict 用开放寻址（3.6+ 紧凑双表：indices + entries），平均 O(1)、最坏 O(n)；3.7 起语言规范保证插入顺序（遍历 entries 物理顺序）。list 不可哈希不能作键；hash() 自 3.3 起带随机盐（防碰撞攻击），跨进程不稳定，不能用于持久化或分片。"},{"kind":"coding","q":"用 dict 计数判断字母异位词（valid-anagram）","stem":"完成 LeetCode 242（valid-anagram）：定义 def is_anagram(s, t) 判断两个字符串是否互为字母异位词。要求： 1. 用 dict 或 collections.Counter 做字符计数； 2. 说明为何比「排序后比较」复杂度更优（O(n) vs O(n log n)）； 3. 扩展到 Unicode 场景说明差异。 题面与示例以链接为准（不在本文件复述题干…","opts":[],"ans":"import sys def is_anagram(s, t): if len(s) != len(t): return False cnt = {} for ch in s: cnt[ch] = cnt.get(ch, 0) + 1 for ch in t: if ch not in cnt: return Fals…","why":"计数法 O(n) 时间、O(k) 空间（k 为字符集大小）；排序法 O(n log n)。Counter 内部就是 dict 计数，C 层实现更快。Unicode 场景需注意「组合字符」（如 é 可能是单码位或 e+́ 两个码位），此时应先 unicodedata.normalize('NFC', s)。"},{"kind":"coding","q":"用 set 求交集并保序（intersection-of-two-arrays）","stem":"完成 LeetCode 349（intersection-of-two-arrays）：定义 def intersection(nums1, nums2) 返回两数组的交集（去重）。要求： 1. 先用 set 完成 O(n+m) 的去重交集； 2. 额外实现保序版本：结果按 nums1 中首次出现的顺序排列（提示：用 dict.fromkeys 去重保序，再配合 set 判断）； 3. 说明为何…","opts":[],"ans":"import sys def intersection_ordered(nums1, nums2): s2 = set(nums2) return [x for x in dict.fromkeys(nums1) if x in s2] if __name__ == '__main__': lines = sys.st…","why":"set 基于哈希表，成员判断平均 O(1)，整体 O(n+m)；若直接双重循环则是 O(n·m)。dict.fromkeys(nums1) 利用 3.7+ 字典保序特性去重且保留首次出现顺序，再配合 set 做 O(1) 判断，得到保序结果。这是「set 提速 + dict 保序」的经典组合。"}],"works":[{"h":"[[0]] 3 是共享引用，不是三个新列表","d":"python a = [[0]] 3 a[0].append(1) print(a) # [[0, 1], [0, 1], [0, 1]] <- 全被改 原理： 把同一个对象的指针复制 n 份。对不可变元素（[0]3）无害，对可变元素就是灾难。 正解：a = [[0] for _ in range(3)]（每次迭代新建）。同理 dic…"},{"h":"浅拷贝后原地改子对象，原容器跟着变","d":"python a = [[1, 2], [3, 4]] b = a[:] # 或 list(a) / copy.copy(a) b[0].append(99) print(a) # [[1, 2, 99], [3, 4]] 原理：浅拷贝只新建一层\"指针数组\"，槽位仍指向同一批子对象。替换槽位（b[0] = [9]）只影响 b；原地改子…"},{"h":"遍历容器时修改它（最隐蔽的 bug）","d":"python # 列表：会跳过元素 a = [1, 2, 3, 4] for x in a: if x % 2 == 0: a.remove(x) print(a) # [1, 3] 看起来对，但 [1,2,3,4,5,6] 会得到 [1,3,5]? 实际 [1,3,5] 之外还可能漏 # 字典：直接报错 d = {'a':1, 'b…"},{"h":"用 is 比较数值 / 字符串","d":"python a, b = 256, 256; a is b # True（小整数缓存 -5~256） a, b = 257, 257; a is b # False（不要依赖！同一行常量折叠时可能又变 True） 原理：is 比对象标识（id），== 比值。CPython 缓存小整数与部分短字符串（驻留）。 正解：数值/字符串比较一…"},{"h":"可变对象当 dict 键 / 定义了 __eq__ 却忘了 __hash__","d":"python {[1, 2]: 'x'} # TypeError: unhashable type: 'list' class P: def __eq__(self, o): return True {P(): 1} # TypeError: unhashable type: 'P' 原理：定义 __eq__ 会把 __hash__…"},{"h":"在 list 头部频繁增删（pop(0) / insert(0, x)）","d":"原理：list 是连续指针数组，头部操作要 memmove 搬移全部 n 个指针 → O(n)。循环里做就是 O(n²)。 正解：用 collections.deque（两端 O(1)）；或先 reverse() 再从尾部处理。"},{"h":"把生成器当列表用（一次性耗尽）","d":"python g = (x for x in range(3)) print(list(g)) # [0, 1, 2] print(list(g)) # [] <- 已耗尽 原理：生成器是惰性的一次性迭代器，消费完就停。 正解：需多次遍历就转 list(g) 保存，或重新构造生成器（用生成器函数而非表达式，可重复调用）。"},{"h":"用 x in some_list 做大量成员判断","d":"原理：list 的 in 是线性扫描 + 逐个 __eq__，O(n)；循环里判断就是 O(n²)。 正解：把待查集合转 set / dict（平均 O(1)）——这是最常见的性能优化手段，往往一行改动带来数量级提升。"}],"asks":[{"q":"CPython 的 dict 是怎么实现的？为什么 Python 3.7 之后遍历顺序稳定？扩容时机是什么？","a":"实现：dict 用开放寻址（open addressing）哈希表，而非链地址法。 - 3.6 起改为紧凑双表布局：indices（稀疏索引表，存 entries 下标）+ entries（紧凑实体表，按插入顺序紧密存放 hash/key/value）。 - 为什么 3.7 起有序：遍历直接按 entries 的物理顺序走，而 entries 是紧凑追加的——顺序天然等于插入顺序。3.7 把这一行…","fu":["为什么 dict 的键必须可哈希？哈希冲突了怎么办？","set 和 dict 在实现上有什么关系？"],"tag":"通用/字节"},{"q":"为什么 list.append 是摊销 O(1)？扩容时到底发生什么？insert(0, x) 又为何是 O(n)？","a":"结构：list 是过度分配的动态指针数组（ob_item 指向 PyObject 数组，带 allocated 预留槽位）。 - append：若 ob_size < allocated，直接写入 → O(1)。满时才 realloc 扩容并搬移全部指针 → 单次 O(n)。 - 摊销 O(1)：扩容按约 1.125 倍 + 小列表固定余量增长（CPython 公式 new = n + n>>3…","fu":["list 和 tuple 的内存差多少？为什么？","什么场景下用 array 模块或 NumPy 替代 list？"],"tag":"通用/字节"},{"q":"浅拷贝和深拷贝的区别？copy.deepcopy 如何处理循环引用？哪些对象不能深拷贝？","a":"浅拷贝：只复制容器本身（新建一层指针数组），元素对象仍共享。a[:]、list(a)、a.copy()、copy.copy(a) 四者等价。 - 替换槽位（b[0] = [9]）只影响副本；原地改共享子对象（b[0].append(1)）会同时影响原容器。 深拷贝：copy.deepcopy(a) 递归重建整张对象图，新旧完全独立。 - 循环引用处理：内部维护 memo 字典（id(原对象) →…","fu":["如何为自定义类实现 __deepcopy__？","为什么 a = [[0]] 3 会互相影响？"],"tag":"通用/阿里"},{"q":"一个对象「可哈希」意味着什么？为什么定义了 __eq__ 后对象就不可哈希了？","a":"可哈希（hashable）要求： 1. 有 __hash__ 返回生命周期内不变的 int； 2. 有 __eq__，且满足 a == b ⟹ hash(a) == hash(b)（反过来不要求，碰撞由 __eq__ 兜底）； 3. 哈希值必须基于不可变字段。 为什么定义 __eq__ 会让对象不可哈希：Python 规定，类中定义了 __eq__ 但未定义 __hash__ 时，__hash__…","fu":["为什么 tuple 里装了 list 就不能作为 dict 的键？","如何让自定义对象既能比较相等又能放进 set？"],"tag":"通用/字节"}]},{"id":"py-ch04","subj":"python","title":"标准库：os/sys/re/datetime/json","summary":"os 与路径操作；sys .argv 与解释器；re 正则；datetime 时间处理；json 序列化；常用内建模块协同。","concepts":[{"id":"py-ch04/01-os-and-pathlib-paths","file":"01-os-and-pathlib-paths.md","title":"os 与 pathlib：路径对象、目录遍历与跨平台","kind":"flow","secs":[{"h":"1. 路径不是字符串：pathlib 把路径变成一等对象","s":"早期 Python 用 os.path 把路径当普通字符串处理：","c":{"lang":"python","code":"import os\n\np = os.path.join(\"data\", \"raw\", \"a.csv\")\nbase = os.path.splitext(os.path.basename(p))[0]"}},{"h":"2. 目录遍历：walk / iterdir / rglob 怎么选","s":"os.walk 独有的价值是剪枝：","c":{"lang":"python","code":"import os\n\nfor root, dirs, files in os.walk(\"proj\"):\n    dirs[:] = [d for d in dirs if d not in {\".git\", \"__pycache__\", \"node_modules\"}]\n    for f in files:\n        ..."}},{"h":"3. 环境变量与进程信息","s":"写环境变量时注意：os.environ 是进程内的映射，改它只影响当前进程与其子进程，不会写回 shell。","c":{"lang":"python","code":"import os\n\nos.environ[\"APP_MODE\"]                    # KeyError 若不存在\nos.environ.get(\"APP_MODE\", \"dev\")         # 推荐：给默认值\nos.getenv(\"APP_MODE\", \"dev\")              # 等价写法\n\nos.getpid()                               # 当前进程号\nos.cpu_count()                            # 逻辑核数\nos.name                                   # 'nt'(Windows) / 'posix'"}},{"h":"4. 跨平台陷阱清单","s":"最后一条尤其阴险：\"C:\\new\\test\" 里的 \\n 是换行符、\\t 是制表符，字符串内容早已不是你以为的路径。要么用 raw string，要么用 /（Windows 的 API 同时接受 / 与 \\）。","c":null},{"h":"5. 速记","s":"","c":null}]},{"id":"py-ch04/02-sys-cli-and-import-path","file":"02-sys-cli-and-import-path.md","title":"sys：命令行参数、导入路径与标准流","kind":"flow","secs":[{"h":"1. sys.argv：最原始的入参通道","s":"sys.argv 是一个列表：argv[0] 是脚本名（或 -c / -m 时的占位），之后是用户给的参数，全部是字符串。","c":{"lang":"python","code":"import sys\n\nif len(sys.argv) < 3:\n    sys.stderr.write(\"usage: tool.py <in> <out>\\n\")\n    sys.exit(2)                     # 约定：2 表示「用法错误」\n\nsrc, dst = sys.argv[1], sys.argv[2]"}},{"h":"2. sys.path 与导入解析顺序","s":"import foo 时，Python 按 sys.path 的顺序查找：","c":{"lang":"python","code":"import sys\n\nprint(sys.path[0])           # 通常是脚本目录\nsys.path.insert(0, \"/opt/lib\")   # 把自定义目录提到最前"}},{"h":"3. 标准流与输出重定向","s":"「管道时块缓冲」是个实战坑：python tool.py | grep foo 时，print() 的输出会攒到 8KB 才刷，导致你看不到实时进度。解法：","c":{"lang":"python","code":"print(\"processing...\", flush=True)      # 单次强制刷新\n# 或启动时：python -u tool.py"}},{"h":"4. 解释器信息与编码","s":"版本判断要用 sys.version_info，不要解析 sys.version 字符串：","c":{"lang":"python","code":"import sys\n\nsys.version            # '3.13.12 (main, ...)'\nsys.version_info       # sys.version_info(major=3, minor=13, ...) —— 用它做版本判断\nsys.platform           # 'win32' / 'linux' / 'darwin'\nsys.getdefaultencoding()   # 'utf-8'（Python 3 固定）\nsys.getfilesystemencoding()  # 文件系统编码，Windows 上是 'utf-8'（3.6+）"}},{"h":"5. 速记","s":"","c":null}]},{"id":"py-ch04/03-datetime-naive-aware-and-timezone","file":"03-datetime-naive-aware-and-timezone.md","title":"datetime：naive / aware、时区与夏令时","kind":"flow","secs":[{"h":"1. 三种时间表示，别混着用","s":"Python 的 datetime 对象分两类：","c":{"lang":"python","code":"from datetime import datetime, timezone\n\na = datetime(2026, 10, 7, 14, 30)                       # naive\nb = datetime(2026, 10, 7, 14, 30, tzinfo=timezone.utc)  # aware\na - b     # TypeError: can't subtract offset-naive and offset-aware datetimes"}},{"h":"2. timestamp() 的坑：naive 会被当成本地时间","s":"naive.timestamp() 会假定 naive 是本地时间，因此输出依赖 TZ 环境变量与系统时区设置。同一份代码在北京和纽约跑，得到的秒数差 12 小时，而且不报错。","c":{"lang":"python","code":"from datetime import datetime, timezone\n\nnaive = datetime(2026, 10, 7, 14, 30)\nnaive.timestamp()            # ⚠️ 按【本机时区】解释！换台机器结果就变\naware = datetime(2026, 10, 7, 14, 30, tzinfo=timezone.utc)\naware.timestamp()            # ✅ 确定：1780842600.0"}},{"h":"3. 时区：zoneinfo 与夏令时","s":"Python 3.9+ 引入 zoneinfo（PEP 615），用 IANA 时区数据库：","c":{"lang":"python","code":"from datetime import datetime\nfrom zoneinfo import ZoneInfo\n\nsh = ZoneInfo(\"Asia/Shanghai\")\nny = ZoneInfo(\"America/New_York\")\n\nt = datetime(2026, 3, 8, 2, 30, tzinfo=ny)   # 纽约 2026-03-08 02:30\nprint(t.utcoffset())          # ⚠️ 该时刻处于 DST 跳变窗口\nprint(t.astimezone(sh))       # 转上海"}},{"h":"4. 格式化与解析：strftime / strptime 与 ISO 8601","s":"strptime 的两个易错指令：%m 是月（01–12）、%M 是分（00–59）；%y 是两位年（26 → 2026）、%Y 是四位年。搞混会得到「分钟=1、秒=26」这种看似正常但完全错误的结果。","c":{"lang":"python","code":"from datetime import datetime, timezone\n\nt = datetime(2026, 10, 7, 14, 30, 5, tzinfo=timezone.utc)\nt.strftime(\"%Y-%m-%d %H:%M:%S\")        # '2026-10-07 14:30:05'\nt.isoformat()                          # '2026-10-07T14:30:05+00:00'\n\ndatetime.fromisoformat(\"2026-10-07T14:30:05+08:00\")   # ✅ 3.11+ 支持大部分 ISO 8601\ndatetime.strptime(\"2026-10-07\", \"%Y-%m-%d\")           # 需要显式格式"}},{"h":"5. 速记","s":"","c":null}]},{"id":"py-ch04/04-json-serialization-boundaries","file":"04-json-serialization-boundaries.md","title":"json：序列化边界、参数与自定义编码","kind":"flow","secs":[{"h":"1. 类型映射表：什么能过、什么会炸","s":"json 模块只认识 JSON 规范里的 6 种类型。Python 类型到 JSON 的映射：","c":{"lang":"python","code":"import json\n\njson.dumps({1: \"a\"})          # '{\"1\": \"a\"}'  ✅ int key 被静默转成字符串\njson.dumps({(1, 2): \"a\"})     # ❌ TypeError：tuple key 不能转"}},{"h":"2. dumps / dump 常用参数","s":"两个工程要点：","c":{"lang":"python","code":"import json\n\ndata = {\"b\": 1, \"a\": [1, 2], \"note\": \"中文\"}\n\njson.dumps(data, ensure_ascii=False)     # 保留中文（默认 True 会转成 \\\\u4e2d\\\\u6587）\njson.dumps(data, indent=2)               # 缩进美化（给人和 git diff 看）\njson.dumps(data, sort_keys=True)         # 键排序（让 diff 稳定）\njson.dumps(data, separators=(\",\", \":\"))  # 紧凑：去掉空格，省带宽"}},{"h":"3. 无法直接序列化时：default 与自定义编码器","s":"给 default 传一个函数，遇到不认识的类型就调用它：","c":{"lang":"python","code":"import json\nfrom datetime import datetime, timezone\n\ndef enc(o):\n    if isinstance(o, datetime):\n        return o.isoformat()\n    if isinstance(o, (set, frozenset)):\n        return sorted(o)              # 排序保证确定性！\n    raise TypeError(f\"不可序列化: {type(o).__name__}\")\n…"}},{"h":"4. json vs pickle：为什么不要用 pickle 传数据","s":"pickle 的安全问题是致命的：pickle.loads(untrusted_bytes) 可以执行任意代码（通过 __reduce__ 构造）。所以：","c":null},{"h":"5. 速记","s":"","c":null}]}],"exams":[{"kind":"choice","q":"PurePosixPath('/a/b/../c') 的 parts 与字符串形态","stem":"关于 pathlib.PurePosixPath('/a/b/../c')，下列说法正确的是？","opts":[{"k":"A","t":"parts 为 ('/', 'a', 'c')，字符串为 /a/c（自动规范化掉 ..）"},{"k":"B","t":"parts 为 ('/', 'a', 'b', '..', 'c')，字符串保留 /a/b/../c（不做规范化）"},{"k":"C","t":"构造时直接抛 ValueError"},{"k":"D","t":"parts 为 ('a', 'b', '..', 'c')（首部斜杠被丢弃）"}],"ans":"B","why":"pathlib 的 PurePath 只做语法处理，不会去访问文件系统，也不折叠 ..——.. 作为普通名字片段保留在 parts 里。要折叠必须显式调用 resolve()（会访问文件系统、解析符号链接）或无参的 os.path.normpath。很多人的直觉是「路径都该被规范化」，这是 pathlib 最常被误解的一点。"},{"kind":"choice","q":"naive 与 aware datetime 相减","stem":"datetime(2026, 1, 1) - datetime(2026, 1, 1, tzinfo=timezone.utc) 的结果是？","opts":[{"k":"A","t":"timedelta(days=0)，因为两者时刻相同"},{"k":"B","t":"timedelta(hours=-8)，按 UTC+8 本地时区自动换算"},{"k":"C","t":"抛 TypeError: can't subtract offset-naive and offset-aware da…"},{"k":"D","t":"抛 ValueError"}],"ans":"C","why":"Python 拒绝在 naive 与 aware 之间做算术，因为无法确定 naive 到底代表哪个时区，静默猜测会埋下 8 小时级的事故。正确做法：全链路统一用 aware（推荐 UTC 存储，展示时再转本地），或在边界处显式 replace(tzinfo=...) / astimezone(...) 明确语义。"},{"kind":"output","q":"json.dumps 的类型变换","stem":"以下代码的输出是什么？ python import json print(json.dumps((1, 2))) print(json.dumps({1: 'a'})) print(json.dumps(float('nan'))) print(json.dumps('中文'))","opts":[],"ans":"[1, 2]\\n{\"1\": \"a\"}\\nNaN\\n\"\\\\u4e2d\\\\u6587\"","why":"① tuple 被序列化为 JSON 数组（[1, 2]）——json 没有 tuple 类型，往返 loads 后变成 list；② JSON 的键必须是字符串，整数键被 int→str 转换，往返后 {1: 'a'} 变成 {'1': 'a'}，这是「往返不保真」的经典来源；③ NaN 是 Python 扩展，标准 JSON 不允许（allow_nan=False 会抛 V…"},{"kind":"fix_error","q":"open() 不指定 encoding 的跨平台事故","stem":"下面这段在生产上偶发 UnicodeDecodeError（开发机正常、CI 或容器里崩），请指出根因并给出修复： python def load_cfg(path): with open(path) as f: return f.read()","opts":[],"ans":"根因：未显式指定 encoding，Python 会使用 locale.getpreferredencoding(False)。Linux/容器（LANG=C）下常是 ASCII 或 UTF-8， Windows 简中下是 GBK/cp936——同一份含中文的 UTF-8 配置文件，在 GBK 环境下解码必然抛 Uni…","why":"教科书示例为简短省略 encoding，但任何进仓库的 IO 代码都必须显式指定编码。配套要点：newline='' 交给 csv 模块处理换行；二进制场景用 'rb' 避免任何解码。"},{"kind":"choice","q":"sys.path 的搜索顺序","stem":"执行 python script.py 时，import mymod 的搜索顺序是？","opts":[{"k":"A","t":"当前工作目录 → 标准库 → site-packages"},{"k":"B","t":"脚本所在目录（sys.path[0]）→ PYTHONPATH → 标准库 → site-packages"},{"k":"C","t":"标准库 → 脚本所在目录 → site-packages"},{"k":"D","t":"只搜索 site-packages"}],"ans":"B","why":"关键点：sys.path[0] 在脚本模式下是脚本所在目录，而 python -c 或交互式下才是当前工作目录（cwd）。这一差异导致「开发机上 python src/app.py 正常、装成包后 import 失败」的经典事故。此外 -m 模式会把 cwd 插到最前，进一步改变结果。排查手段：import sys; print(sys.path) 与 python -X im…"},{"kind":"coding","q":"用 pathlib 递归统计目录中的文件类型分布","stem":"实现 ext_stats(root)，递归统计 root 下所有文件的扩展名分布，返回 dict[ext, count]。要求： 1. 用 pathlib.Path.rglob('') 遍历，只用 is_file() 判定； 2. 无扩展名的文件归入 '<none>'； 3. 扩展名统一小写（README.MD 与 a.md 合并）； 4. 结果按数量降序、同数量按扩展名字典序排序后返回。","opts":[],"ans":"from pathlib import Path def ext_stats(root): counts = {} for p in Path(root).rglob(''): if not p.is_file(): continue ext = p.suffix.lower() or '<none>' counts[…","why":"rglob('') 一次性产出所有层级的条目（含目录），必须用 is_file() 过滤。p.suffix 只取最后一个后缀（a.tar.gz → .gz），要取全部后缀用 p.suffixes。排序用 (-count, ext) 双键实现「数量降序 + 名字升序」，注意用元组排序而不是先按 count 排再二次排。"},{"kind":"coding","q":"简化 Unix 风格路径（LeetCode 71）","stem":"给定一个 Unix 风格绝对路径字符串，将其简化为规范路径（.. 回退、. 与多余斜杠忽略、栈空时 .. 不越界）。 请到 LeetCode 71 查看完整题面并用 Python 实现。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行 Unix 风格绝对路径（不含换行）。 输出：简化后的规范路径，占一行。","opts":[],"ans":"题面见 https://leetcode.cn/problems/simplify-path/","why":"典型解法：按 / 切分，用列表当栈——'' 与 '.' 跳过；'..' 时若栈非空则 pop()（栈空则忽略，因为根目录的上一级还是根）；其余 push。最后 '/' + '/'.join(stack)。进阶：可对照本题与 pathlib.PurePosixPath 的行为差异——PurePosixPath 不折叠 ..，resolve() 才折叠且会访问文件系统，这也解释了为…"},{"kind":"coding","q":"安全的原子写入：临时文件 + os.replace","stem":"实现 atomic_write(path, text)：写文件的过程中若进程被杀，不能留下半截文件，且不能留下临时文件残留。 要求： 1. 先写入同目录下的临时文件（同目录才能保证 os.replace 是同一文件系统内的原子 rename）； 2. 显式 encoding='utf-8'； 3. 成功后用 os.replace 覆盖目标（Windows 与 POSIX 都原子）； 4. 失败时清…","opts":[],"ans":"import os import tempfile from pathlib import Path def atomic_write(path, text): path = Path(path) path.parent.mkdir(parents=True, exist_ok=True) fd, tmp = temp…","why":"要点三处：① 临时文件必须与目标同目录（mkstemp(dir=...)），跨文件系统的 replace 退化成「复制+删除」就不再原子；② flush() + os.fsync() 保证数据落到磁盘而非只到页缓存，否则掉电仍可能丢；③ 用 except BaseException 而非 except Exception，KeyboardInterrupt 也要走清理分支。os…"}],"works":[{"h":"\"C:\\new\\test\" 里的 \\n 是换行符","d":"反斜杠转义在路径字符串里会静默生效，字符串内容早已不是你以为的路径。正确写法：r\"C:\\new\\test\"、Path(r\"C:/new/test\")，或用正斜杠 \"C:/new/test\"（Windows API 同样接受）。"},{"h":"用 os.environ[\"KEY\"] 读配置","d":"变量缺失时抛 KeyError，本地有值、线上没注入就崩。正确写法：os.environ.get(\"KEY\", default) 或 os.getenv(\"KEY\", default)，默认值必须显式给出。"},{"h":"dirs = [...] 想剪枝却没生效","d":"os.walk 只在 dirs 被原地修改时才看到变化。正确写法：dirs[:] = [d for d in dirs if ...]，切片赋值才是原地替换。"},{"h":"list(Path(d).rglob(\"\")) 在大目录上吃爆内存","d":"一次性物化整棵树。正确写法：直接迭代生成器 for p in Path(d).rglob(\"\")，需要顺序时才 sorted()（且评估规模）。"},{"h":"依赖 rglob / iterdir 的返回顺序","d":"底层 readdir 顺序因文件系统而异，同目录增删文件后还会变。正确写法：任何需要可复现的场景（测试、快照、CI）显式 sorted(...)，并指定 key。"},{"h":"在项目根目录放 json.py / random.py / types.py","d":"脚本目录在 sys.path 首位，会遮蔽标准库同名模块，导致依赖库 import json 拿到你的文件，报出无法定位的 AttributeError。正确写法：用包结构（src/mypkg/）+ 可安装包，不要靠 sys.path.append 打补丁。"},{"h":"python tool.py | grep x 时看不到实时输出","d":"stdout 连到管道时是块缓冲（默认 8KB）。正确写法：print(..., flush=True)，或启动加 -u（python -u tool.py）。"},{"h":"成功时 sys.exit(1)、失败时 sys.exit(2)","d":"违反 POSIX 约定会让 CI/脚本的 if cmd; then 判断全错。正确约定：0 成功、1 通用业务错误、2 命令行用法错误（argparse 默认）、128+n 被信号 n 终止。"}],"asks":[{"q":"为什么 Python 要禁止 naive 与 aware datetime 直接相减？生产上你选哪种策略？","a":"禁止的原因：naive datetime 只是一个「没有时区的日历时刻」，它无法确定对应哪个 UTC 瞬间；aware 则携带明确的 UTC 偏移。两者相减的语义未定义，静默猜一个时区可能造成数小时级偏差（跨 DST 甚至出现 23/25 小时的一天）。Python 选择直接抛 TypeError 而不是猜。 生产策略（推荐）： 1. 存储与传输一律 UTC aware（datetime.now(…","fu":["2026-03-08 是美国 DST 开始日，ZoneInfo('America/New_York') 下 02:30…","time.time() 与 datetime.now().timestamp() 有什么区别？后者在极端情况下会出错吗？"],"tag":"后端/基础架构"},{"q":"json.dumps 往返（dumps → loads）不保真的地方有哪些？","a":"按「最容易踩」排序： 1. 键类型坍缩：JSON 的键只能是字符串，{1: 'a'} → {'1': 'a'}。修复：保证键本身是字符串，或往返后显式还原类型。 2. tuple → list：(1, 2) → [1, 2]。需要 tuple 就自己 tuple(...) 还原。 3. NaN / Infinity 是扩展语法：Python 默认输出裸 NaN，但标准 JSON 不允许，Go/Ja…","fu":["如何处理 datetime / Decimal / 自定义类？default= 与自定义 JSONEncoder 的区别…","orjson / msgspec 相比标准库快在哪里？代价是什么？"],"tag":"后端/数据工程"},{"q":"pathlib 的 resolve() 有哪些副作用？什么时候不该用它？","a":"Path.resolve() 做的不只是字符串规范化，它会： 1. 访问文件系统——逐级解析符号链接（symlink）； 2. 在严格模式下（strict=True）路径不存在就抛 FileNotFoundError（3.6+ 默认 strict=False，会尽量解析已存在的最长前缀）； 3. 把相对路径按 cwd 展开成绝对路径； 4. 折叠 ..（但注意：对 symlink 而言折叠 ..…","fu":["Path.is_relative_to() 与字符串 startswith 判断前缀相比，安全性好在哪？","os.path.realpath 与 Path.resolve 有何差异？"],"tag":"Python 工程/安全"},{"q":"生产上写文件为什么要「临时文件 + os.replace」，而不是直接 open(path, 'w')？","a":"open(path, 'w') 会立刻截断目标文件：此刻起，原内容已丢，新内容还没写完。于是存在三个真实风险窗口： 1. 进程崩溃 / 被杀：留下 0 字节或半截文件，下游读到损坏配置； 2. 并发读：另一个进程可能读到「写了一半」的状态； 3. 磁盘写满 / 掉电：即使 write 返回成功，数据可能还在页缓存里。 原子替换方案：写入同目录的临时文件 → flush() + os.fsync()…","fu":["多进程同时写同一配置，如何避免丢失更新（lost update）？","fsync 对 SSD 与对网络文件系统（NFS）的语义差异？"],"tag":"基础架构/存储"}]},{"id":"py-ch05","subj":"python","title":"文件与 IO：读写/上下文管理器/序列化","summary":"文本与二进制文件读写；with 上下文管理器与 __enter__/__exit__；csv/json 文件；路径库 pathlib；缓冲与编码。","concepts":[{"id":"py-ch05/01-text-vs-binary-and-encoding","file":"01-text-vs-binary-and-encoding.md","title":"文本模式与二进制模式：编码、换行与 BOM","kind":"flow","secs":[{"h":"1. 两种模式，两套世界","s":"open() 的 mode 决定了 Python 给你的是 str 还是 bytes：","c":{"lang":"python","code":"# 危险：文本模式 + 通用换行，会把 \\r\\n 统一成 \\n\nwith open(\"proto.txt\", \"r\") as f:\n    data = f.read()          # 原始 \\r\\n 已丢失\n\n# 正确：需要原始字节就用二进制\nwith open(\"proto.txt\", \"rb\") as f:\n    data = f.read()          # 原样保留"}},{"h":"2. encoding 必须显式写","s":"不写 encoding 时，Python 使用 locale.getpreferredencoding(False)，","c":null},{"h":"3. 换行符与 newline 参数","s":"文本模式的通用换行（universal newlines）会把 \\r\\n、\\r、\\n 统一翻译成 \\n。","c":{"lang":"python","code":"# 想让 \\n 原样写出（例如生成 CSV / HTTP 报文），必须禁用翻译\nwith open(\"out.csv\", \"w\", encoding=\"utf-8\", newline=\"\") as f:\n    ..."}},{"h":"4. BOM：看不见的三个字节","s":"UTF-8 BOM 是文件开头的 EF BB BF。它能被 utf-8-sig 编解码器识别并剥离：","c":{"lang":"python","code":"# 读到 \"中文\" 却显示 \"\\ufeff中文\" —— 说明文件带 BOM 而用了 \"utf-8\"\nwith open(\"from_excel.csv\", \"r\", encoding=\"utf-8-sig\") as f:\n    text = f.read()       # \\ufeff 被自动去掉"}},{"h":"5. errors 策略：遇到坏字节怎么办","s":"open(..., errors=...) 有五档，最常用三档：","c":null},{"h":"6. 一次读写的内存代价","s":"f.read() 把整个文件读进内存：峰值内存 ≈ 文件大小 × (1 + 解码后膨胀系数)。","c":{"lang":"python","code":"with open(\"big.log\", \"r\", encoding=\"utf-8\") as f:\n    for line in f:            # 逐行，缓冲区级别复用\n        process(line)         # 内存 O(单行最大长度)"}},{"h":"7. 文件名与路径的编码：surrogateescape 的用武之地","s":"前面讨论的都是「文件内容」的编码，但 Python 里还有一处更容易被忽略：文件名本身的编码。","c":null}]},{"id":"py-ch05/02-context-manager","file":"02-context-manager.md","title":"上下文管理器：with 的三件事与自定义写法","kind":"flow","secs":[{"h":"1. with 究竟做了什么","s":"等价于：","c":{"lang":"python","code":"with open(\"a.txt\") as f:\n    data = f.read()"}},{"h":"2. __exit__ 的返回值是开关","s":"__exit__(exc_type, exc_val, exc_tb) 有三个语义：","c":{"lang":"python","code":"class Suppress:\n    def __enter__(self):\n        return self\n    def __exit__(self, et, ev, tb):\n        return et is not None      # 有异常就吞掉"}},{"h":"3. 自定义上下文管理器","s":"最小可用形态是「类 + 两个方法」；只有清理逻辑的函数式写法用","c":{"lang":"python","code":"import contextlib, time\n\n@contextlib.contextmanager\ndef timer(label):\n    t0 = time.perf_counter()\n    try:\n        yield                      # 这里把控制权交回 with 块\n    finally:\n        print(label, \"耗时档位:\", \"快\" if time.perf_counter() - t0 < 1 else \"慢\")"}},{"h":"4. 一个真实的资源管理器：原子写入","s":"「写文件到一半崩了」会留下半截文件。工程做法是","c":{"lang":"python","code":"import os, pathlib, tempfile\n\ndef atomic_write_text(path, text, encoding=\"utf-8\"):\n    path = pathlib.Path(path)\n    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix=\".tmp-\")\n    try:\n        with os.fdopen(fd, \"w\", encoding=encoding, newline=\"\") as f:\n            f.write(text)\n            f.flush()                  # 推到 OS\n…"}},{"h":"5. 契约层面的形式化","s":"上下文管理器实现的是资源获取即初始化（RAII）思想在 Python 中的投影：","c":null},{"h":"6. 常见的错误用法","s":"","c":{"lang":"python","code":"# ✗ 一个 with 里塞多个不相关资源 -> 异常时难以判断哪个失败\nwith open(\"a\"), open(\"b\"), open(\"c\"):\n    ...\n\n# ✓ 用括号换行（Python 3.10+）或 ExitStack，保持可读\nwith (\n    open(\"a\", encoding=\"utf-8\") as fa,\n    open(\"b\", encoding=\"utf-8\") as fb,\n):\n…"}},{"h":"7. ExitStack：数量不定时怎么管资源","s":"前面写的都是「几个资源就写几个 with」的静态写法。但当资源数量在运行时才知道——","c":null}]},{"id":"py-ch05/03-buffering-flush-fsync","file":"03-buffering-flush-fsync.md","title":"缓冲、flush、fsync：write 成功不等于数据安全","kind":"stack","secs":[{"h":"1. 三层存储，三次\"提交\"","s":"一次 f.write(\"hello\") 到数据真正落在磁盘上，跨过三层：","c":{"lang":"python","code":"with open(\"log.txt\", \"w\", encoding=\"utf-8\") as f:\n    f.write(\"important\")\n    # 此刻：数据在 Python 缓冲区（或者刚推到 OS 页缓存），磁盘上什么都没有\n# with 退出 -> 隐式 flush -> 数据在 OS 页缓存，仍未落盘"}},{"h":"2. 缓冲策略与 buffering 参数","s":"open() 的 buffering：","c":null},{"h":"3. flush 与 fsync 的分工","s":"每次 fsync 都要等磁盘确认，机械盘数量级毫秒。因此常见折中：","c":{"lang":"python","code":"import os\n\nf = open(\"db.log\", \"a\", encoding=\"utf-8\")\nf.write(\"commit tx=42\")\nf.flush()                  # ① Python 缓冲 -> OS 页缓存\nos.fsync(f.fileno())       # ② OS 页缓存 -> 磁盘\nf.close()"}},{"h":"4. 原子写入的完整形态","s":"缺任一都可能留下\"半截文件\"或\"孤儿临时文件\"。","c":{"lang":"python","code":"import os, pathlib, tempfile\n\ndef atomic_write_bytes(path, data: bytes):\n    path = pathlib.Path(path)\n    fd, tmp = tempfile.mkstemp(dir=str(path.parent), prefix=\".tmp-\")\n    try:\n        with os.fdopen(fd, \"wb\") as f:\n            f.write(data)\n            f.flush()\n…"}},{"h":"5. 崩溃一致性：为什么\"覆盖写\"是不安全的","s":"考虑 f = open(\"cfg.json\", \"w\") 后写 1 MB 数据，在第 500 KB 时断电：","c":null},{"h":"6. 大文件处理的内存红线","s":"","c":null},{"h":"7. fdatasync、O_DIRECT 与「落盘」的三种强度","s":"fsync 并不是落盘强度的唯一档位，实际有三级，代价依次升高、语义依次变强：","c":null}]},{"id":"py-ch05/04-csv-json-and-streaming","file":"04-csv-json-and-streaming.md","title":"csv 与 json：结构化文件的读写与边界","kind":"compare","secs":[{"h":"1. csv：为什么必须 newline=\"\"","s":"csv.writer 自己负责写 \\r\\n（RFC 4180 规定行尾是 CRLF）。","c":{"lang":"python","code":"import csv\n\n# ✓ 官方文档写法\nwith open(\"out.csv\", \"w\", encoding=\"utf-8\", newline=\"\") as f:\n    w = csv.writer(f)\n    w.writerow([\"城市\", \"销量\"])\n    w.writerow([\"北京\", 120])\n\n# 读回来同理\n…"}},{"h":"2. json：ensure_ascii 与编码","s":"两者都合法，只是可读性不同。要点：","c":{"lang":"python","code":"import json\n\ndata = {\"城市\": \"北京\", \"销量\": 120}\n\n# 默认 ensure_ascii=True：非 ASCII 被转成 \\uXXXX 转义\nprint(json.dumps(data))                          # {\"\\u57ce\\u5e02\": \"\\u5317\\u4eac\", ...}\nprint(json.dumps(data, ensure_ascii=False))      # {\"城市\": \"北京\", ...}"}},{"h":"3. 序列化格式的取舍","s":"Web 服务、跨组织传输一律不用 pickle；需要类型保真且安全时选","c":null},{"h":"4. 流式处理与内存","s":"标准 JSON 不支持流式追加（一个数组必须整体合法）。","c":{"lang":"python","code":"import csv\n\n# 常量内存：适合超大文件\nwith open(\"huge.csv\", encoding=\"utf-8\", newline=\"\") as f:\n    reader = csv.reader(f)\n    header = next(reader)\n    total = 0\n    for row in reader:\n        total += int(row[1])"}},{"h":"5. 半行 JSON：流式解析时的错误恢复","s":"按行读取 JSONL（每行一个独立 JSON）时，一定会遇到「读到半行」的情况：","c":null}]}],"exams":[{"kind":"choice","q":"open 的 mode 参数语义","stem":"关于 open(path, mode)，下列说法错误的是？","opts":[{"k":"A","t":"encoding 只在文本模式下合法，二进制模式传入会抛 ValueError"},{"k":"B","t":"'a' 模式在文件不存在时会创建新文件"},{"k":"C","t":"'a' 模式会把写指针定位到文件开头，从而覆盖原有内容"},{"k":"D","t":"'r+' 要求文件必须已存在，否则抛 FileNotFoundError"}],"ans":"C","why":"区分 w（截断）与 a（末尾追加）是日常最容易踩的坑：用 w 重跑一次任务就把上次结果清空。"},{"kind":"choice","q":"__exit__ 的返回值语义","stem":"自定义上下文管理器的 __exit__(self, exc_type, exc, tb) 返回 True 意味着什么？","opts":[{"k":"A","t":"异常会被重新抛出，返回 True 只是记录日志"},{"k":"B","t":"异常被视为已处理，不再向外传播"},{"k":"C","t":"只对 KeyboardInterrupt 生效，其它异常照常抛出"},{"k":"D","t":"返回 True 是非法的，解释器会抛 TypeError"}],"ans":"B","why":"对比 C：细节上返回真值后 traceback 也就丢了，所以吞噬异常要非常克制，通常只吞特定异常类型。"},{"kind":"output","q":"写出顺序推断","stem":"python from pathlib import Path p = Path('x.txt') f = open(p, 'w', encoding='utf-8') f.write('abc') print(p.stat().st_size) f.flush() print(p.stat().st_size) f.write('de') print(p.stat().st_size) f.cl…","opts":[],"ans":"","why":"注意 flush() 与 os.fsync() 不等价：前者到 OS 页缓存，后者才要求落盘。"},{"kind":"fix_error","q":"BOM 导致的 JSON 解析失败","stem":"下面代码在读取用 Excel 另存的 UTF-8 文件时抛 json.decoder.JSONDecodeError: Expecting value: line 1 column 1 (char 0)，请修好。 python import json with open('config.json', encoding='utf-8') as f: cfg = json.load(f)","opts":[],"ans":"import json def load_config(path): # utf-8-sig 在读的时候自动剥掉开头的 BOM（U+FEFF） with open(path, encoding='utf-8-sig') as f: return json.load(f) def dumps_config(cfg): #…","why":"同类问题还有：BOM 混进 CSV 首列列名，导致 DictReader 的 key 变成 '\\ufeffid'，按 'id' 取值恒为 None。"},{"kind":"coding","q":"手写 CSV 行解析器（不依赖 csv 模块）","stem":"实现 parse_csv_line(line)：把一行 CSV 文本解析成字段列表。规则：逗号分隔；字段可被双引号包裹；被包裹时内部 \"\" 表示一个 \"，且内部的逗号/换行不视为分隔符。返回字段列表。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行 CSV 文本（字段可能被双引号包裹，内部 \"\" 表示一个引号）。 输出：…","opts":[],"ans":"import sys def parse_csv_line(line): fields, buf, i, n, in_quotes = [], [], 0, len(line), False while i < n: c = line[i] if in_quotes: if c == '\"': if i + 1 < n…","why":"状态机方法：in_quotes 是唯一状态位，遇到 \"\" 先探测下一字符再决定是转义还是收尾。该题正是 csv 模块内部的简化版。"},{"kind":"coding","q":"流式统计大文件（不整体载入）","stem":"实现 count_lines_and_max_len(path)：返回 (行数, 最长行字符数)，要求逐行处理、不把整个文件读进内存。","opts":[],"ans":"def count_lines_and_max_len(path): count = 0 max_len = 0 with open(path, 'r', encoding='utf-8', errors='replace') as f: for line in f: # 迭代器按块读，内存占用与文件大小无关 coun…","why":"for line in f 走的是 TextIOWrapper.__next__，内部按缓冲块读取，不会一次性 read()。用 f.read().splitlines() 则会把全文载入，10 GB 日志直接 OOM。"},{"kind":"choice","q":"解码错误的不可逆性","stem":"字节串 b'caf\\xe9 ok'（本意是 latin-1 的 café ok）用 decode('utf-8', errors='replace') 再 encode('utf-8')，结果是？","opts":[{"k":"A","t":"可以完整恢复为原来的 b'caf\\xe9 ok'"},{"k":"B","t":"得到 b'caf\\xef\\xbf\\xbd ok'：\\xe9 已被 U+FFFD 替换，原字节永久丢失"},{"k":"C","t":"第一步 decode 就会抛 UnicodeDecodeError，因为指定了 errors='replace' 也不生…"},{"k":"D","t":"得到 UTF-8 编码的 b'café ok'，与原始字节一致"}],"ans":"B","why":"所以排错顺序永远是：先确认真实编码（看响应头/文件声明/嗅探），再决定是否用宽松策略；宽松策略只用于「宁可丢几个字也要跑通」的场景。"},{"kind":"choice","q":"flush 与 fsync 的边界","stem":"关于 f.flush() 与 os.fsync(f.fileno())，正确的是？","opts":[{"k":"A","t":"flush() 已经把数据写到磁盘，进程崩溃或断电都不会丢"},{"k":"B","t":"flush() 只把数据交给 OS 页缓存（进程崩溃可保、断电不可保）；fsync() 才触发落盘，两者都做才算断电安全"},{"k":"C","t":"fsync() 只同步元数据，文件内容仍可能丢失"},{"k":"D","t":"flush() 与 fsync() 是同一件事的两个名字"}],"ans":"B","why":"代价是 fsync 要等磁盘，QPS 敏感场景常改成 append + 定期 fsync；数据库的 WAL 就是在这个矛盾上做折中。"}],"works":[{"h":"不写 encoding","d":"open(\"f.txt\") 跟随系统 locale，中文 Windows 上是 GBK，换到 Linux 就乱码或抛 UnicodeDecodeError。正确：任何文本文件读写都显式写 encoding=\"utf-8\"。"},{"h":"用文本模式读写二进制内容","d":"文本模式会对 \\r\\n 做规范化、对字节做解码，图片/压缩包/协议报文会被改坏。正确：\"rb\" / \"wb\"。"},{"h":"csv 不加 newline=\"\"","d":"csv 自己写 \\r\\n，不禁用换行翻译会让 Windows 上多出 \\r，Excel 里显示空行。正确：open(..., newline=\"\")。"},{"h":"把 \\ufeff 当成数据","d":"带 BOM 的文件用 utf-8 读，首字符会多出 \\ufeff，导致 csv.DictReader 的第一个键名被污染、json.loads 直接报错。正确：读 utf-8-sig；排查时先 print(repr(text[:5]))。"},{"h":"errors=\"ignore\" 掩盖数据损坏","d":"坏字节被静默丢弃，CSV 里往往丢的正是分隔符，导致字段错位且极难定位。正确：\"strict\" 显式失败，或 \"replace\" + 统计坏字节数。"},{"h":"以为 with 退出就落盘了","d":"with 只 flush 到 OS 页缓存，断电/容器被 kill 仍会丢。正确：需要抗断电就 flush() + os.fsync(f.fileno())。"},{"h":"fsync 放在循环里","d":"每条记录都等磁盘确认，吞吐量断崖式下降。正确：批量提交或定时组提交；只读元数据不同步时用 os.fdatasync。"},{"h":"os.rename 覆盖已存在文件","d":"Windows 上目标存在会直接抛错，跨平台行为不一致。正确：统一用 os.replace。"}],"asks":[{"q":"文本模式和二进制模式的区别，什么时候必须用 binary？","a":"文本模式（'r'/'w'）返回 str，open 时做两件额外的事：按 encoding 解码/编码，以及按 newline 做换行翻译。二进制模式（'rb'/'wb'）返回 bytes，不做任何转换，也不能传 encoding。 必须用 binary 的场景：图片/音视频/压缩包等非文本数据；需要精确控制换行字节（如生成 CRLF 的 Windows 批处理）；做校验和、加密、协议帧解析；把二进…","fu":["open(..., 'rb') 传 encoding= 会怎样？","为什么要给 errors='replace'？会有什么代价？"],"tag":"通用/Python 基础"},{"q":"with 语句的本质是什么？为什么它比 try/finally 好？","a":"with 是上下文管理器协议的语法糖：进入时调用 __enter__()（返回值绑定给 as 的名字），离开时无论正常还是异常都调用 __exit__(exc_type, exc, tb)。 它比手写 try/finally 好在：① 资源释放逻辑跟资源定义放在一起，不会漏；② 支持嵌套与组合（ExitStack）；③ 可复用成形如 contextlib.suppress/nullcontext…","fu":["__exit__ 返回 True 后异常去哪了？","ExitStack 解决什么真实问题？"],"tag":"通用/Python 进阶"},{"q":"写了数据但文件大小是 0，可能有哪些原因？","a":"按可能性排序排查： 1. 缓冲区未刷（最常见）：写入量小于缓冲阈值，数据停在用户态。flush() 或 close() 后大小才变。注意用 with 就不会有这个问题。 2. 文件对象已关闭但你以为还开着：后续 write 抛 ValueError: I/O operation on closed file，而之前那次没落盘的内容可能已丢。 3. 看错了路径：Path.cwd() 与脚本目录不同…","fu":["flush() 之后一定能在另一个进程里读到吗？","原子写的标准姿势是什么？"],"tag":"工程排查/Python 进阶"},{"q":"CSV 读写有哪些必踩的坑？","a":"1. 不用 csv 模块手拼字符串：字段含逗号/引号/换行时会直接破坏列结构。 2. 忘了 newline=''：读时字段内的 \\r\\n 会被通用换行先行切成两行，行结构错乱；写时 Windows 上会多出空行。 3. BOM 污染首列名：用 Excel 存过的文件首列 key 变成 '\\ufeffid'，row['id'] 恒为 None。读时用 utf-8-sig。 4. 全部当字符串：csv…","fu":["csv.Sniffer 在什么情况下会失败？","如何给 CSV 加流式校验（行数/列数一致性）？"],"tag":"数据工程/Python"}]},{"id":"py-ch06","subj":"python","title":"正则与文本处理：re/分组/替换","summary":"re 编译与匹配；分组与命名组；贪婪/非贪婪；sub 替换；文本清洗与解析；与 str 方法取舍。","concepts":[{"id":"py-ch06/01-re-entrypoints","file":"01-re-entrypoints.md","title":"01 · re 的四个入口：match / search / fullmatch / finditer","kind":"compare","secs":[{"h":"1.1 入口对照表","s":"","c":{"lang":"python","code":"import re\ns = \"abc123\"\nprint(bool(re.match(r\"\\d+\", s)))      # False —— 开头不是数字\nprint(bool(re.search(r\"\\d+\", s)))     # True  —— 串里有数字\nprint(bool(re.fullmatch(r\"[a-z]+\\d+\", s)))  # True —— 整串正好是 字母+数字"}},{"h":"1.2 findall 的分组陷阱","s":"findall 的返回形态取决于有没有分组，这是最容易踩的坑：","c":null},{"h":"1.3 编译与复用","s":"re.compile(p) 返回 Pattern 对象，可复用。Python 内部有缓存（re._MAXCACHE，默认 512 条），所以循环里直接写 re.match(p, s) 通常也不会重复编译 —— 但一旦模式数量超过缓存容量…","c":{"lang":"python","code":"NUM = re.compile(r\"\\d+\")\nprint(NUM.findall(\"a1b22c333\"))   # ['1', '22', '333']"}},{"h":"1.4 flags：最常用的三个","s":"","c":{"lang":"python","code":"multi = \"a\\nb\\nc\"\nprint(len(re.findall(r\"^.\", multi)))          # 1\nprint(len(re.findall(r\"^.\", multi, re.M)))    # 3\nprint(re.findall(r\"a.b\", \"a\\nb\"))             # []\nprint(re.findall(r\"a.b\", \"a\\nb\", re.S))       # ['a\\nb']"}}]},{"id":"py-ch06/02-groups-and-backreferences","file":"02-groups-and-backreferences.md","title":"02 · 分组、命名组与反向引用","kind":"flow","secs":[{"h":"2.1 三类括号","s":"","c":{"lang":"python","code":"import re\nm = re.match(r\"((\\d)(\\d))-(\\d)\", \"12-3\")\nprint(m.groups())   # ('12', '1', '2', '3')\nprint(m.group(0))   # '12-3'  —— 整个匹配\nprint(m.group(1))   # '12'    —— 最外层组"}},{"h":"2.2 命名组与 groupdict","s":"命名组的真实价值在替换模板里：\\g<mo> 比 \\2 可读得多，也不怕插入新组导致编号漂移。","c":{"lang":"python","code":"m = re.match(r\"(?P<y>\\d{4})-(?P<mo>\\d{2})\", \"2026-10\")\nprint(m.group(\"y\"), m.group(\"mo\"))   # 2026 10\nprint(m.groupdict())                 # {'y': '2026', 'mo': '10'}"}},{"h":"2.3 反向引用：\\1 与 \\g<1>","s":"反向引用（backreference）表示\"匹配与前面某个组相同的内容\"。它是正则超出正则语言能力的典型例子。","c":{"lang":"python","code":"import re\n# \\1 表示与组 1 相同的内容\nprint(re.search(r\"\\b(\\w+)\\s+\\1\\b\", \"hello hello\").group(0))   # 'hello hello'\n# 替换模板里引用组：把 'world hello' 换成 'hello world'\nprint(re.sub(r\"(\\w+)\\s+(\\w+)\", r\"\\2 \\1\", \"world hello\"))       # 'hello world'"}},{"h":"2.4 分组的回溯视角","s":"每个捕获组都是一次\"记录位置\"的动作。组越多，回溯时保存/恢复的状态越多。这引出两条工程建议：","c":null}]},{"id":"py-ch06/03-greedy-and-catastrophic-backtracking","file":"03-greedy-and-catastrophic-backtracking.md","title":"03 · 贪婪、非贪婪、占有量词与回溯爆炸","kind":"flow","secs":[{"h":"3.1 三种量词语义","s":"","c":{"lang":"python","code":"import re\nprint(re.findall(r\"<.*>\",  \"<a><b>\"))   # ['<a><b>']\nprint(re.findall(r\"<.*?>\", \"<a><b>\"))   # ['<a>', '<b>']"}},{"h":"3.2 回溯爆炸：为什么会指数级","s":"考虑 r\"(a+)+b\" 作用在 \"aaaaaaaaaaaaaaaaaaaaaaaaac\"（25 个 a + c）上：","c":null},{"h":"3.3 三种解法","s":"","c":null},{"h":"3.4 回溯的正面价值","s":"不要因此把回溯当\"坏东西\"。.? 的惰性、\\1 的反向引用、零宽断言，都依赖回溯。它们的共同点是：能表达 DFA 表达不了的东西。所以工程上的正确姿势是：","c":null}]},{"id":"py-ch06/04-sub-replace-and-text-cleaning","file":"04-sub-replace-and-text-cleaning.md","title":"04 · sub 替换、文本清洗与\"正则 vs 解析库\"的边界","kind":"compare","secs":[{"h":"4.1 re.sub 的三种替换形态","s":"","c":{"lang":"python","code":"import re\nprint(re.sub(r\"(\\w+)\\s+(\\w+)\", r\"\\2 \\1\", \"world hello\"))       # 字符串模板\nprint(re.sub(r\"\\d+\", lambda m: str(int(m.group()) * 2), \"a1b22\"))  # 函数\nprint(re.sub(r\"a\", \"X\", \"aaa\", count=1))                        # 只替换第一个"}},{"h":"4.2 文本清洗的典型配方","s":"清洗任务几乎都可以拆成\"三步\":","c":{"lang":"python","code":"import re, unicodedata\ns = \"  Ｈｅｌｌｏ，世界   \"\nprint(repr(unicodedata.normalize(\"NFKC\", s).strip()))  # 'Hello,世界'"}},{"h":"4.3 零宽断言（边界匹配）","s":"","c":{"lang":"python","code":"import re\nprint(re.findall(r\"\\d+(?=元)\", \"10元 20个 30元\"))       # ['10', '30'] 后面是\"元\"\nprint(re.findall(r\"(?<=\\$)\\d+\", \"$10 $20 30\"))           # 定宽回顾\ntry:\n    re.findall(r\"(?<=\\d+)\\w\", \"12a\")\nexcept re.error as e:\n    print(\"变量长 lookbehind 报错:\", str(e)[:40])"}},{"h":"4.4 什么时候不该用正则","s":"这是本章最重要的一节。有形式语法的东西，请用解析库：","c":{"lang":"python","code":"import re, json\nbad = r'\\{\"id\":\\s*(\\d+)\\}'   # 看起来能用，但遇嵌套/转义就崩\nobj = {\"id\": 1, \"tags\": [{\"id\": 2}]}\nprint(\"正则漏掉嵌套:\", re.findall(bad, json.dumps(obj)))   # ['1'] —— 内层 id=2 没抓到（也抓不对）\nprint(\"解析器全对:\", json.loads(json.dumps(obj))[\"tags\"][0][\"id\"])  # 2"}},{"h":"4.5 可读性：re.X 与预编译常量","s":"复杂模式用 re.X（verbose）可以换行 + 加注释：","c":{"lang":"python","code":"import re\nDATE = re.compile(r'''\n    (?P<y>\\d{4}) - (?P<m>\\d{2}) - (?P<d>\\d{2})   # 年-月-日\n''', re.X)\nprint(DATE.match(\"2026-10-08\").groupdict())"}}]},{"id":"py-ch06/05-regex-practical-recipes","file":"05-regex-practical-recipes.md","title":"凯喵实战手记：正则不是「匹配神器」，是「带回溯的状态机」","kind":"flow","secs":[{"h":"1. 贪婪匹配会「贪」到不该吞的地方","s":"凯喵第一次用 . 提取标签内容，结果整段被吞：","c":{"lang":"python","code":"import re\ns = \"<a>hi</a> <a>bye</a>\"\nre.findall(r\"<a>(.*)</a>\", s)   # ['hi</a> <a>bye'] ← 贪婪吃到底\nre.findall(r\"<a>(.*?)</a>\", s)  # ['hi', 'bye']      ← 非贪婪停在第一处"}},{"h":"2. 灾难性回溯：一行正则拖垮整台服务","s":"凯喵写过用来校验输入的 (a+)+$，结果遇到 \"aaaaaaaaaaaaaaaaaaaaaaaa!\" 直接卡死：","c":{"lang":"python","code":"re.match(r\"(a+)+$\", \"a\"*25 + \"!\")   # 指数级回溯，CPU 打满"}},{"h":"3. 分组与反向引用：配对才是真功夫","s":"凯喵做 HTML 清洗时用反向引用保证开闭标签一致：","c":{"lang":"python","code":"re.sub(r'<(\\w+)>(.*?)</\\1>', r'\\2', s)   # \\1 引用第一个分组「标签名」"}},{"h":"4. 命名分组：让提取结果可读","s":"凯喵解析日志时，编号分组很快数到崩溃：","c":{"lang":"python","code":"m = re.search(r\"(?P<ip>\\d+\\.\\d+\\.\\d+\\.\\d+) .*?(?P<code>\\d{3})\", line)\nif m:\n    print(m.group(\"ip\"), m.group(\"code\"))"}},{"h":"5. re.sub 的替换函数：不只是字符串","s":"凯喵做脱敏时，用函数决定每个匹配怎么换：","c":{"lang":"python","code":"def mask(m):\n    return m.group(1) + \"***\" + m.group(3)\nre.sub(r\"(\\d{3})-(\\d{2})-(\\d{4})\", mask, text)"}},{"h":"6. 字符类与转义：. 不匹配换行","s":"凯喵跨行匹配内容时一度怀疑人生：","c":{"lang":"python","code":"re.search(r\"start.*end\", \"start\\nmiddle\\nend\", re.DOTALL)  # 加 DOTALL 才跨行"}},{"h":"7. search vs match：一个从开头一个从任意位置","s":"凯喵因为记混两者，校验永远通过：","c":{"lang":"python","code":"re.match(r\"\\d+\", \"abc123\")    # None，match 强制从开头\nre.search(r\"\\d+\", \"abc123\")   # <Match>，从任意位置找"}},{"h":"8. 预编译：热点路径别反复编译","s":"凯喵在循环里反复写 re.search(r\"...\", s)，性能差十倍：","c":{"lang":"python","code":"pat = re.compile(r\"\\d{4}-\\d{2}-\\d{2}\")\nfor line in huge_log:\n    pat.search(line)   # 复用同一编译对象"}},{"h":"9. 原子组与占有量词：高级防回溯","s":"凯喵处理嵌套结构时，用占有量词掐断无谓回溯：","c":{"lang":"python","code":"re.match(r\"\\d++\\w\", \"123abc\")   # \\d++ 一旦匹配绝不吐回，立刻失败而非回溯"}},{"h":"10. 锚点与边界：\\b 才是「单词边界」","s":"凯喵想匹配独立的 cat，却匹配到 category：","c":{"lang":"python","code":"re.findall(r\"cat\", \"category cat\")     # ['cat', 'cat']\nre.findall(r\"\\bcat\\b\", \"category cat\") # ['cat']  ← 只在单词边界"}},{"h":"11. re.VERBOSE：把复杂正则写可读","s":"凯喵把一行鬼画符拆成带注释的多行：","c":{"lang":"python","code":"pat = re.compile(r\"\"\"\n    (?P<year>\\d{4}) - (?P<month>\\d{2}) - (?P<day>\\d{2})\n\"\"\", re.VERBOSE)"}},{"h":"12. 正则不是瑞士军刀：日期/JSON 别硬刚","s":"凯喵最后悟了：正则擅长「模式」，不擅长「结构」：","c":{"lang":"python","code":"# 日期合法性别用正则：\\d{4}-\\d{2}-\\d{2} 会放过 2026-13-45\nfrom datetime import datetime\ndatetime.strptime(\"2026-13-45\", \"%Y-%m-%d\")  # ValueError，正确做法"}},{"h":"凯喵复盘：正则到底是「模式」还是「语法」","s":"这 12 个现场背后是同一个判断：正则擅长描述「模式」，不擅长描述「结构」。贪婪/非贪婪、灾难性回溯、. 不匹配换行，都是「模式匹配」层面的事；而日期合法性、JSON、HTML 层级，本质是「结构 + 语义」，交给专用解析器更可靠。写正…","c":null},{"h":"🧑‍💻 程序员视角","s":"贪婪匹配 . 会吞到最后一个可能位置，<div>.</div> 在多个 div 时会一次匹配到底——加 ? 变非贪婪，或改用更精确的字符类。灾难性回溯是正则最危险的一面：(a+)+b 在长串 aaaa... 上会指数级回溯，一行正则能把…","c":null},{"h":"🎓 博士生视角","s":"正则表达式在理论上等价于「有限自动机」（不含反向引用时），但多数引擎用「回溯实现」以获得反向引用等扩展能力，代价是最坏情况指数复杂度。RE2 等引擎用 NFA 模拟保证线性时间，代价是不支持反向引用与前后瞻。理解「回溯 vs 自动机」的…","c":null},{"h":"📚 考研者视角","s":"Python/后端面试高频：","c":null}]}],"exams":[{"kind":"choice","q":"re.match 与 re.fullmatch 的行为差异","stem":"给定模式 r\"\\d+\"，对字符串 \"abc123\" 调用 re.match 与 re.fullmatch，结果分别是什么？","opts":[{"k":"A","t":"re.match 返回 None，re.fullmatch 也返回 None"},{"k":"B","t":"re.match 返回 '123'，re.fullmatch 返回 None"},{"k":"C","t":"re.match 返回 None，re.fullmatch 返回 '123'"},{"k":"D","t":"两者都返回 '123'"}],"ans":"A","why":"match 只从字符串开头尝试，abc 不以数字开头，所以直接返回 None；fullmatch 还要求整串匹配，同样不满足。若换成 re.search(r\"\\d+\", \"abc123\") 才会命中 123。"},{"kind":"output","q":"写出 findall 在含分组时的返回结果","stem":"re.findall(r\"(\\w)=(\\d+)\", \"a=1 b=22\") 的结果是什么？","opts":[],"ans":"","why":"findall 在模式含多个分组时返回元组列表：每个元组是一个匹配的各分组内容。若含 1 个分组返回字符串列表；若不含分组则返回整个匹配串的列表。"},{"kind":"fix_error","q":"修复「动态拼装模式」导致的误匹配","stem":"下面代码想统计 key 出现的次数，但结果偏大。指出原因并给出修法。 python import re key = \"a.b\" print(len(re.findall(key, \"a.b axb a-b\")))","opts":[],"ans":"import re key = \"a.b\" print(\"错误版本 :\", len(re.findall(key, \"a.b axb a-b\"))) fixed = re.escape(key) print(\"修好后 :\", len(re.findall(fixed, \"a.b axb a-b\"))) print(\"转…","why":"原模式里 . 是元字符（匹配任意字符），于是 axb、a-b 都被算进来。动态拼装模式时字面量部分必须 re.escape()，得到 a\\.b，只匹配真实点号。"},{"kind":"output","q":"写出 sub 使用编号组模板的结果","stem":"re.sub(r\"(\\d{4})-(\\d{2})-(\\d{2})\", r\"\\3/\\2/\\1\", \"2026-10-08\") 的结果是什么？","opts":[],"ans":"","why":"模板里 \\1 \\2 \\3 分别引用第 1、2、3 个捕获组。原串组内容为 2026、10、08，按 \\3/\\2/\\1 重排后为 08/10/2026。命名组等价写法是 \\g<d>.\\g<m>.\\g<y>。"},{"kind":"choice","q":"后行断言的长度约束","stem":"下列哪个正则可以被成功编译？","opts":[{"k":"A","t":"(?<=a+)b"},{"k":"B","t":"(?<=\\d)x"},{"k":"C","t":"(?<=abc)d"},{"k":"D","t":"(?<=a|bc)e"}],"ans":"C","why":"Python 的 re 要求后行断言（lookbehind）定宽：a+、a、a{1,3} 都是变长，编译即报 look-behind requires fixed-width pattern。只有 (?<=aa) 这类固定长度可用。若确实需要变长，改用分组捕获：re.findall(r\"a+(b)\", s)。"},{"kind":"coding","q":"实现支持 . 与 的正则匹配（DP）","stem":"实现一个函数 is_match(s, p)，支持 . 匹配任意单字符、 匹配零个或多个前一个元素，要求整串匹配。 只提供题号与链接（题面正文见平台，遵循本项目合规约定），请自行在平台完成。这里给出可直接运行的参考实现与自测。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：两行，第一行字符串 s，第二行模式 p（只含小写字母…","opts":[],"ans":"import sys def is_match(s, p): n, m = len(s), len(p) dp = [[False] (m + 1) for _ in range(n + 1)] dp[0][0] = True for j in range(2, m + 1): if p[j - 1] == '': d…","why":"用 dp[i][j] 表示 s[:i] 与 p[:j] 是否匹配。关键是 的两种转移：匹配 0 次（dp[i][j-2]）与再匹配一次（dp[i-1][j]，前提是当前字符匹配 p[j-2]）。时间复杂度 O(n·m)，空间 O(n·m)。"},{"kind":"coding","q":"把连续空白压缩为单个空格并去首尾","stem":"实现 squash(text)：把任意长度的空白（含制表符）压缩成一个半角空格，并去掉首尾空白。 只提供题目入口链接（题面正文见平台），此处给出可直接运行的参考实现与自测。 <!-- judge-io --> 判题 I/O 约定（提交完整程序：从 stdin 读、向 stdout 写） 输入：一行文本（可能含多余空格/制表符）。 输出：压缩并去首尾后的文本，用 [文本] 包裹输出，便于看出空结果。","opts":[],"ans":"import re import sys _WS = re.compile(r'\\s+') def squash(text): return _WS.sub(' ', text).strip() if __name__ == '__main__': print('[' + squash(sys.stdin.readli…","why":"\\s+ 匹配连续空白（含 \\t、\\n），sub(\" \", ...) 压成单空格，strip() 去掉首尾。核心优化点是把模式编译一次并复用，避免在循环里反复走 re 的缓存查找。"},{"kind":"coding","q":"用占有量词消除回溯风险","stem":"下面模式在恶意输入上会严重回溯。请写一个函数 safe_scan(text)，把每个 <tag> 内容取出，并保证在超长无闭合尖括号的输入上线性完成（不得修改语义）。给出可直接运行的对比实现。","opts":[],"ans":"import re risky = re.compile(r\"<.+>\") safe = re.compile(r\"<[^>]++>\") def safe_scan(text): return safe.findall(text) sample = \"<a><bc><def>\" print(\"risky :\", ris…","why":"把 . 换成否定字符类 [^>]，再用占有量词 ++ 禁止回吐，等价于「不允许跨过 >」。这样引擎不会在失败时尝试所有切分方式，把最坏情况从指数级降为线性。这是「回溯炸弹」的标准工程解法。"}],"works":[{"h":"re.match 被当成整串匹配","d":"re.match(r\"\\d+\", \"12abc\") 返回 Match，你可能以为它校验通过了。校验格式一律用 re.fullmatch（或自己加 ^...$）。"},{"h":"findall 有分组时只返回分组","d":"re.findall(r\"(\\d)\", \"a1b2\") 得到 ['1','2']；两个分组时得到元组列表。想拿整串匹配就别加捕获组（用 (?:...)），或改用 finditer + m.group(0)。"},{"h":"替换模板没用原始字符串","d":"re.sub(p, \"\\1\", s) 里的 \"\\1\" 会被 Python 先当八进制转义解释。必须写 r\"\\1\"，或统一用 r\"\\g<1>\"。"},{"h":"\\12 的歧义","d":"想表达\"组 1 后面跟字面 2\"时写 r\"\\12\"，实际会被解析为组 12，导致 re.error: invalid group reference。一律用 r\"\\g<1>2\"。"},{"h":"非捕获组不占编号","d":"((\\d)(?:-)(\\d)) 里只有 3 个捕获组；混用 (?:...) 后按\"看起来的第几个括号\"取组必然错位。"},{"h":"嵌套分组编号是\"外层更小\"","d":"((\\d)(\\d)) 里组 1 是整体 12，组 2、3 才是内层；很多人以为是内层先编号。"},{"h":"对 None 直接取组","d":"re.match(...) 失败返回 None，此时 m.group(1) 抛 AttributeError。正确写法：m.group(1) if m else None。"},{"h":"^ / $ 默认只管整串首尾","d":"多行日志里想按行匹配必须加 re.M；同理 . 默认不匹配 \\n，跨行匹配要加 re.S。这两个 flag 作用互不相干。"}],"asks":[{"q":"re.match、re.search、re.fullmatch 有什么区别？校验格式应该用哪个？","a":"match：只从字符串开头尝试，允许后面有多余字符。 - search：从任意位置扫描，找到第一个匹配即返回。 - fullmatch：要求整串匹配（等价于 ^...$）。 校验格式（手机号、IPv4、日期）必须用 fullmatch。用 search 会放过 \"192.168.1.1 extra\" 这类带尾巴的串，是最常见的安全隐患。","fu":["re.match 与在模式前加 ^ 有何差别？（答案：几乎等价，但 re.M 多行模式下 ^ 会匹配每行行首，match…","如何只匹配「一整行」？（答案：re.M + ^...$，或用 fullmatch 配合逐行处理）"],"tag":"字节跳动/美团"},{"q":"什么是「正则回溯炸弹」？如何防御？","a":"当模式中存在多重嵌套量词（如 (a+)+b）且输入匹配失败时，回溯引擎会尝试所有可能的切分方式，数量随长度指数增长，导致 CPU 打满（ReDoS）。 防御手段： 1. 消除嵌套量词：把 (a+)+ 改写成 a+。 2. 用否定字符类替代 .：<.+> 换成 <[^>]++>。 3. 使用占有量词 / 原子组（Python 3.11+ 支持 ++、+、?+）。 4. 限制输入长度，并在入口处做白名…","fu":["占有量词和原子组在语义上有区别吗？（答案：a++ 等价于 (?>a+)，都是「一旦匹配就不回吐」）","Python 的 re 是 NFA 还是 DFA？（答案：回溯式 NFA，故最坏情况指数；DFA 引擎是线性但表达力弱）"],"tag":"阿里/华为"},{"q":"\\w、\\d 在 Python 3 里默认匹配什么？为什么有时要加 re.ASCII？","a":"Python 3 的 str 模式默认使用 Unicode 语义：\\w 匹配任何「词字符」，包括汉字、全角字符；\\d 匹配 Unicode 数字。 如果输入域是 ASCII（日志、HTTP 头、标识符），全角字符混入会导致误匹配甚至注入。此时加 re.ASCII 把语义收窄到 ASCII 范围。反之，处理中文分词/文本抽取时要依赖 Unicode 语义，不能加该 flag。","fu":["re.ASCII 会影响 re.I 吗？（答案：会，大小写折叠限制在 ASCII 范围）","bytes 模式下的默认语义是什么？（答案：本来就是 ASCII 语义，无需 flag）"],"tag":"字节跳动/快手"},{"q":"后行断言（lookbehind）有什么限制？变长的需求怎么办？","a":"Python 的 re 要求后行断言定宽，(?<=a+)、(?<=a)、(?<=a{1,3}) 都会在编译期抛 re.error。可选写法： - 改成定宽：(?<=aa)。 - 改用分组捕获：re.findall(r\"a+(b)\", s) 只取需要的部分。 - 使用 re 之外支持变长 lookbehind 的引擎（如第三方 regex 模块）。 另外要记住断言不消耗字符：(?<=密码=)\\w+…","fu":["先行断言有定宽限制吗？（答案：没有，lookahead 可以是任意复杂模式）","断言里的分组会被编号吗？（答案：会，除非写成 (?:...)）"],"tag":"腾讯/百度"}]},{"id":"py-ch07","subj":"python","title":"并发：threading/asyncio","summary":"GIL 与多线程边界；threading 与锁；queue 线程安全；asyncio 协程与事件循环；同步原语与并发模型取舍。","concepts":[{"id":"py-ch07/01-gil-and-threading-boundary","file":"01-gil-and-threading-boundary.md","title":"01 · GIL 与线程边界：什么时候多线程真的有效","kind":"compare","secs":[{"h":"1.1 GIL 是什么","s":"GIL（Global Interpreter Lock）是 CPython 解释器进程内的一把互斥锁。任何线程要想执行 Python 字节码，必须先持有它。","c":{"lang":"python","code":"import sys\nprint(sys.getswitchinterval())   # 0.005 —— 默认 5ms"}},{"h":"1.2 GIL 什么时候释放","s":"这是面试的分水岭。GIL 在三种情况下会让出：","c":null},{"h":"1.3 二维决策：IO 密集 vs CPU 密集","s":"一个可量化的判据：加速比 ≈ 1 说明被 GIL 卡住（或任务太短，开销吃掉收益）；加速比 > 1 说明拿到了并行。","c":{"lang":"python","code":"import time\nfrom concurrent.futures import ThreadPoolExecutor\n\ndef burn(n: int) -> int:\n    s = 0\n    for i in range(n):\n        s += i * i % 7\n    return s\n\n…"}},{"h":"1.4 绕过 GIL 的三条路","s":"1. 多进程：multiprocessing / ProcessPoolExecutor。代价是进程启动开销与数据需序列化（pickle）跨进程传递。","c":null},{"h":"1.5 常见误区","s":"1. 这段活儿 90% 时间在等外部（网络/磁盘/DB）？","c":null}]},{"id":"py-ch07/02-race-and-locks","file":"02-race-and-locks.md","title":"02 · 竞态与锁：Lock / RLock / 条件变量","kind":"flow","secs":[{"h":"2.1 竞态的本质：读-改-写不是一步","s":"x += 1 在 CPython 里被编译成四条字节码：","c":{"lang":"text","code":"LOAD_FAST     x\nLOAD_CONST    1\nBINARY_OP     +=\nSTORE_FAST    x"}},{"h":"2.2 Lock：最小可用的临界区","s":"","c":{"lang":"python","code":"import threading\nlock = threading.Lock()\n\ndef safe_inc():\n    global v\n    for _ in range(1000):\n        with lock:          # 等价于 acquire(); try: ... finally: release()\n            v += 1"}},{"h":"2.3 死锁与四个必要条件","s":"死锁的经典四条件：互斥、请求并保持、不可剥夺、循环等待。破坏任意一条即可预防，工程上最常用的是破坏循环等待：","c":{"lang":"python","code":"# 危险：T1 拿 a 再拿 b，T2 拿 b 再拿 a —— 典型循环等待\n# 安全：所有线程按同一顺序（如按 id 或名称排序）获取锁\nlocks = sorted([lock_a, lock_b], key=id)\nfor lk in locks:\n    lk.acquire()"}},{"h":"2.4 何时不该用锁","s":"1. 列出所有跨线程共享的可变状态（全局变量、类属性、闭包 nonlocal、容器元素）。没有共享 → 直接排除并发 bug。","c":null}]},{"id":"py-ch07/03-queue-and-executor","file":"03-queue-and-executor.md","title":"03 · queue 与线程池：生产/消费与 Future","kind":"flow","secs":[{"h":"3.1 queue.Queue：天生线程安全","s":"queue.Queue 内部已经用锁 + 条件变量实现好了「入队阻塞 / 出队阻塞」，你不需要再加锁：","c":{"lang":"python","code":"import queue, threading\nq = queue.Queue(maxsize=10)     # maxsize>0 时 put 会阻塞（背压）\n\ndef producer():\n    for i in range(20):\n        q.put(i)                 # 队列满则阻塞，天然反压\n    q.put(None)                  # 哨兵：通知消费者收工\n\ndef consumer():\n…"}},{"h":"3.2 线程池：别再手写 Thread","s":"手写 Thread 的三大问题：线程数无上限（可能开成千上万个）、创建开销重复付、异常无人收集。ThreadPoolExecutor 一次解决：","c":{"lang":"python","code":"from concurrent.futures import ThreadPoolExecutor, as_completed\n\ndef fetch(url: str) -> int:\n    return len(url)                      # 演示用，真实场景是网络请求\n\nurls = [\"a\" * 10, \"b\" * 20, \"c\" * 30]\nwith ThreadPoolExecutor(max_workers=4) as ex:\n    print(ex.map(fetch, urls))                    # 惰性迭代器\n    print(list(ex.map(fetch, urls)))              # 保序！\n…"}},{"h":"3.3 Future 与异常传播","s":"Future 是\"未来会有结果\"的占位对象。异常不会在 submit 时抛出，而是在 result() 时重新抛出，且同一个 Future 可重复取：","c":{"lang":"python","code":"f = ex.submit(lambda: 1 / 0)\ntry:\n    f.result()\nexcept ZeroDivisionError as e:\n    print(\"捕获:\", type(e).__name__)"}},{"h":"3.4 进程池：CPU 密集的出口","s":"1. 用 with ThreadPoolExecutor(...) 而不是裸 Thread —— 退出时自动 join。","c":{"lang":"python","code":"from concurrent.futures import ProcessPoolExecutor\n\ndef heavy(n: int) -> int:\n    return sum(i * i % 7 for i in range(n))\n\nwith ProcessPoolExecutor() as ex:\n    print(list(ex.map(heavy, [100_000] * 4)))"}}]},{"id":"py-ch07/04-asyncio-event-loop","file":"04-asyncio-event-loop.md","title":"04 · asyncio：协程、事件循环与取消","kind":"timeline","secs":[{"h":"4.1 协程是「可暂停的函数」","s":"async def 定义的函数调用后不会执行，而是返回一个协程对象；必须交给事件循环（await、asyncio.run、create_task）才会跑。","c":{"lang":"python","code":"import asyncio\n\nasync def hello(tag: str, n: int) -> str:\n    print(\"start\", tag)\n    await asyncio.sleep(0)      # 主动让出控制权（模拟 IO 等待）\n    print(\"end\", tag)\n    return f\"{tag}-{n}\"\n\nasync def main():\n…"}},{"h":"4.2 gather / TaskGroup / wait","s":"","c":{"lang":"python","code":"async def tag(i, d):\n    await asyncio.sleep(d)\n    return i\n\nasync def main():\n    # 完成顺序：sleep 短的先完成\n    order = []\n    async def done(i, d):\n        await asyncio.sleep(d)\n…"}},{"h":"4.3 Task 与取消","s":"create_task 把协程立即排进事件循环（这点与 gather 的\"稍后\"不同）：","c":{"lang":"python","code":"async def worker():\n    try:\n        await asyncio.sleep(10)\n    except asyncio.CancelledError:\n        print(\"被取消，做清理\")\n        raise                    # 惯例：清理后重新抛出\n    finally:\n        print(\"finally 一定执行\")\n\n…"}},{"h":"4.4 最大的坑：阻塞事件循环","s":"事件循环是单线程的。任何同步阻塞调用都会卡死所有协程：","c":{"lang":"python","code":"import time, asyncio, concurrent.futures\n\nasync def bad():\n    time.sleep(0.5)              # ❌ 整个循环停摆\n\nasync def good():\n    loop = asyncio.get_running_loop()\n    with concurrent.futures.ThreadPoolExecutor() as pool:\n        await loop.run_in_executor(pool, time.sleep, 0.5)   # ✅ 丢到线程池"}},{"h":"4.5 asyncio vs threading 选型","s":"1. 你用（或愿意换）的 IO 库有 async 版本吗？有 → asyncio（并发量大时优势最大）。","c":null}]}],"exams":[{"kind":"choice","q":"GIL 存在时，多线程在什么场景仍有收益","stem":"CPython 有全局解释器锁（GIL）。下列哪种场景仍能从多线程获得实际加速？","opts":[{"k":"A","t":"纯 Python 实现的 CPU 密集循环"},{"k":"B","t":"纯 Python 实现的大整数矩阵乘法"},{"k":"C","t":"I/O 密集任务（网络请求、文件读写）——线程等待 I/O 时会释放 GIL"},{"k":"D","t":"用多线程替代多进程做 CPU 并行计算"}],"ans":"C","why":"GIL 只在执行 Python 字节码时互斥；线程在等待 IO 时会释放 GIL，所以阻塞式 IO 的重叠能带来加速。前三项都是纯 Python 计算，同一时刻只有一个线程持有 GIL，无法并行。注意：numpy/hashlib 等 C 扩展在长计算中也会释放 GIL，所以「多线程对计算完全无效」是过头的说法。"},{"kind":"output","q":"判断 count += 1 是否为原子操作","stem":"counter += 1 在 CPython 中需要哪几个字节码步骤？为什么它在没有 GIL 释放点时也可能被中断？","opts":[],"ans":"import dis def bump(counter): counter += 1 return counter dis.dis(bump)","why":"counter += 1 编译为 LOAD_FAST / LOAD_CONST / BINARY_OP / STORE_FAST 四步，不是原子操作。即使字节码之间不主动释放 GIL，CPython 也会按 sys.getswitchinterval()（默认 5ms）抢占式切换线程，所以「读—改—写」三步之间可能被另一线程插入。工程上不能依赖「反正只有一行」。"},{"kind":"fix_error","q":"修复锁顺序不一致导致的死锁","stem":"两个线程分别按 lock_a → lock_b 与 lock_b → lock_a 的顺序获取锁，偶发挂死。指出根因并给出最小修复。","opts":[],"ans":"import threading lock_a = threading.Lock() lock_b = threading.Lock() # 错误写法：两个方向都取同一对锁 -> 循环等待 # def t1(): # with lock_a: # with lock_b: # pass # def t2(): # wi…","why":"死锁的四个必要条件中，最容易在工程上打破的是循环等待：只要所有线程对同一组锁采用全局一致的获取顺序，环就无法形成。另一种修复是用 lock.acquire(timeout=...) 做超时退避，但这只是「打破不可剥夺」，会带来重试复杂度。"},{"kind":"choice","q":"ThreadPoolExecutor 的任务队列与背压","stem":"ThreadPoolExecutor(max_workers=4) 提交 1000 个任务后，若任务处理速度远慢于提交速度，会发生什么？","opts":[{"k":"A","t":"直接抛 RuntimeError，拒绝多余任务"},{"k":"B","t":"任务被放进无界队列缓存，内存持续增长，提交方不被阻塞（没有背压）"},{"k":"C","t":"自动把 max_workers 扩容到 1000"},{"k":"D","t":"队列满后丢弃最旧的任务"}],"ans":"B","why":"ThreadPoolExecutor 的任务队列是无界的（SimpleQueue），submit 永远立刻返回，任务只会在内存里堆积 —— 没有任何背压。要控流必须自己在提交侧加信号量或改用有界队列自行调度。这一点与 asyncio 的 Semaphore 限流动机相同。"},{"kind":"output","q":"gather 中协程的启动与交错顺序","stem":"asyncio.gather(worker('A'), worker('B'))，其中每个 worker 先打印 start 再 await asyncio.sleep(0) 后打印 end。输出的顺序是什么？","opts":[],"ans":"import asyncio log = [] async def worker(name): log.append('start-' + name) await asyncio.sleep(0) log.append('end-' + name) async def main(): await asyncio.gat…","why":"输出为 ['start-A', 'start-B', 'end-A', 'end-B']。gather 先顺序把两个协程包成 Task 并立即调度（A 先跑，跑到 sleep(0) 让出），B 才获得执行机会；两者都在等同一个「下轮就绪」的唤醒，于是按排队顺序恢复。这说明 asyncio 是单线程协作式调度：不遇到 await 就不会切换。"},{"kind":"coding","q":"用同步原语保证三个线程按序执行","stem":"三个线程分别调用 first/second/third，要求无论调度顺序如何，输出恒为 firstsecondthird。只提供题号与链接（题面正文见平台，遵循本项目合规约定），此处给出可直接运行的参考实现与自测。","opts":[],"ans":"import threading class Foo: def __init__(self): self._s1 = threading.Event() self._s2 = threading.Event() self.out = [] def first(self): self.out.append('first'…","why":"核心是用事件传递「前驱已完成」这一事实，而不是用 sleep 猜时序。Event.set() 是幂等且线程安全的；wait() 在已 set 时立即返回，所以即使 second 比 first 早启动也只会阻塞等待。同一类问题也可用 threading.Condition 或 Barrier 实现。"},{"kind":"coding","q":"用 Condition 实现有界缓冲的生产者消费者","stem":"实现一个有界阻塞队列：容量为 cap，生产者满时等待、消费者空时等待，且支持「生产完成后通知消费者退出」。只提供题号与链接（题面正文见平台，遵循本项目合规约定），此处给出可直接运行的参考实现与自测。","opts":[],"ans":"import threading from collections import deque class BoundedBuffer: def __init__(self, cap): self.cap = cap self.q = deque() self.cv = threading.Condition() sel…","why":"三个要点：① 等待必须写在 while 而非 if —— 被唤醒后条件可能已被别的线程破坏（虚假唤醒 / 惊群）；② 变更条件后必须 notify_all()，只 notify() 可能唤醒到不适用的线程造成长等待；③ 用 closed 标志让消费者优雅退出，而不是靠 daemon 强杀（会丢数据）。"},{"kind":"coding","q":"用 asyncio.Semaphore 实现并发限流","stem":"有 20 个异步任务，要求任意时刻并发不超过 3，并返回每个任务的结果；若某任务超时则记为超时而不影响其他任务。给出可直接运行的参考实现与自测。","opts":[],"ans":"import asyncio async def limited(sem, name, delay, log): async with sem: log.append(('enter', name)) try: await asyncio.wait_for(asyncio.sleep(delay), timeout=0…","why":"asyncio.Semaphore 的 async with 在计数耗尽时挂起当前协程并让出事件循环，这是协作式的「等待」——不会阻塞整个循环（区别于 threading.Semaphore）。超时用 asyncio.wait_for，它在超时后取消内部协程，CancelledError 会在 await 点抛出，因此清理必须放在 finally。"}],"works":[{"h":"认为「Python 多线程完全没用」","d":"它在 IO 密集下真有效（阻塞调用前释放 GIL）。正确口径：IO 密集用线程/协程，CPU 密集用多进程；不要一句话打死。"},{"h":"用 CPU 密集任务测多线程并期待加速","d":"GIL 把字节码执行串行化，加速比 $\\le 1$，且上下文切换会让它更慢。改 ProcessPoolExecutor。"},{"h":"以为 x += 1 是原子操作","d":"它是四条字节码（LOAD / LOAD_CONST / BINARY_OP / STORE）。但别把话说满：CPython 下 GIL 通常使其不被打断，\"不原子\"是语义事实、\"可观测到丢失\"是概率事件。教学复现必须用 Barrier 强制交错。"},{"h":"手写 acquire() 忘记 release()","d":"异常路径上留下永久死锁。一律用 with lock:（等价 try/finally）。"},{"h":"用 Lock 做重入","d":"同一线程二次获取会自死锁。类内方法互相调用且都要持锁时用 RLock，并记住获取几次就要释放几次。"},{"h":"持锁做 IO","d":"网络/磁盘等待期间锁不释放，并发度被打到 1，还可能引发连锁超时。锁只锁数据，不锁等待。"},{"h":"加锁顺序不一致导致死锁","d":"T1 拿 a 再拿 b、T2 拿 b 再拿 a 即循环等待。统一按编号升序获取；兜底用 acquire(timeout=...) 把\"等不到\"变成可处理分支。"},{"h":"task_done() 与 get() 数量不配对","d":"q.join() 永远不返回。每次 get() 都要有对应 task_done()（包括收到哨兵那条）。"}],"asks":[{"q":"GIL 是什么？它为什么存在，又带来了什么限制？","a":"定义：CPython 的全局互斥锁，保证同一时刻只有一个线程执行 Python 字节码。 - 存在理由：① 简化 CPython 内部对象（引用计数）的线程安全实现；② 单线程性能更好（无需细粒度锁）；③ 大量 C 扩展默认不是线程安全的。 - 限制：纯 Python 的 CPU 密集任务无法通过多线程并行。 - 但仍有多线程收益：IO 等待 / time.sleep / C 扩展（numpy、z…","fu":["GIL 会在什么时刻被释放？（答案：执行固定字节码条数后按 sys.setswitchinterval() 抢占、遇到阻…","Python 3.13 的「实验性无 GIL 构建」意味着什么？（答案：--disable-gil 是实验特性，需专门构…"],"tag":"字节跳动/腾讯"},{"q":"线程和协程的本质区别是什么？什么时候选协程？","a":"| 维度 | 线程 | 协程（asyncio） | |---|---|---| | 调度方 | 操作系统内核，抢占式 | 事件循环，协作式（遇 await 才切） | | 切换成本 | 内核态切换，较贵 | 用户态，极轻 | | 并发量 | 数百到数千 | 数万级 | | 数据竞争 | 需要锁 | 单线程内天然无竞态（但共享可变状态仍需小心） | | 阻塞调用 | 可用 | 严禁同步阻塞，会卡死整…","fu":["在协程里误调 requests.get 会怎样？（答案：阻塞整个事件循环，所有并发任务一起卡住，必须改用 aiohttp…","run_in_executor 的代价是什么？（答案：切到线程池执行，有线程调度开销，且返回值必须可序列化地跨线程传递）"],"tag":"字节跳动/美团"},{"q":"说说你遇到过的死锁，以及如何定位和预防。","a":"典型场景：两个线程以相反顺序获取同一对锁；或「持锁调用外部服务」导致锁长期不释放。 定位： - threading.enumerate() + sys._current_frames() 打印各线程调用栈，找到同时卡在 lock.acquire 的位置； - faulthandler.dump_traceback_later() 在超时后自动 dump； - Linux 上 gdb / py-sp…","fu":["为什么 RLock 不能解决两把不同锁之间的死锁？（答案：可重入只解决「同一把锁递归获取」，不改变不同锁之间的获取顺序）","threading.Lock 与 RLock 该选哪个？（答案：能不用 RLock 就不用，RLock 会掩盖「重复加锁…"],"tag":"阿里/腾讯"},{"q":"如何用线程池/进程池处理大量任务，并做错误处理？","a":"选择：IO 密集 → ThreadPoolExecutor；CPU 密集 → ProcessPoolExecutor。 要点： - submit 返回 Future，.result() 会重新抛出任务内的异常 —— 不调 result 就永远看不到错误（最常见的坑）。 - map 是懒的且按提交顺序返回，异常在迭代时才冒出来。 - as_completed 按完成顺序产出，适合「谁先好先处理」…","fu":["为什么 ProcessPoolExecutor 里用 lambda 会报错？（答案：PicklingError，lamb…","max_workers 设成多少合适？（答案：IO 密集可远大于核数；CPU 密集通常取 os.cpu_count()）"],"tag":"美团/滴滴"}]},{"id":"py-ch08","subj":"python","title":"数据分析：numpy/pandas 入门","summary":"ndarray 数组与向量化；切片与广播；pandas Series/DataFrame；读写 CSV；分组聚合与基础统计；与列表推导的衔接。","concepts":[{"id":"py-ch08/01-ndarray-and-vectorization","file":"01-ndarray-and-vectorization.md","title":"01 · ndarray 与向量化","kind":"compare","secs":[{"h":"主题一：ndarray 到底特殊在哪","s":"Python 的 list 是一串指针：每个元素都是一个独立的 PyObject，可以放任意类型，也可以随时换类型。代价是——遍历它必须逐个解引用、逐个做类型分派。","c":{"lang":"python","code":"import numpy as np\na = np.array([1, 2, 3])\nprint(a.dtype, a.shape, a.strides)   # int64 (3,) (8,)"}},{"h":"主题二：向量化与循环的对照","s":"用「向量化 vs 显式循环」完成同一件事，能直观看出差别：","c":{"lang":"python","code":"import numpy as np\na = np.arange(1000, dtype=np.float64)\n\n# 写法 A：显式循环 + 预分配\nout = np.empty_like(a)\nfor i in range(a.size):\n    out[i] = a[i] * 2.0 + 1.0\n\n# 写法 B：向量化\n…"}}]},{"id":"py-ch08/02-indexing-slicing-views","file":"02-indexing-slicing-views.md","title":"02 · 索引、切片与视图","kind":"flow","secs":[{"h":"主题一：视图与副本——最容易踩的语义差异","s":"NumPy 的索引分两大类，返回的东西本质不同：","c":{"lang":"python","code":"import numpy as np\na = np.arange(10)\nv = a[2:6]          # 视图\nv[0] = 100\nprint(a[2])         # 100 —— 原数组被改了\n\nc = a[[2, 3]]       # 花式索引 -> 副本\nc[0] = -1\nprint(a[2])         # 仍是 100 —— 原数组没变"}},{"h":"主题二：布尔索引与高级索引","s":"布尔索引用一个同形状的 bool 数组做筛选，返回一维副本：","c":{"lang":"python","code":"import numpy as np\na = np.array([3, -1, 4, -1, 5])\nmask = a > 0\nprint(mask)          # [ True False  True False  True]\nprint(a[mask])       # [3 4 5]\nprint(a[a > 0].sum())  # 12"}}]},{"id":"py-ch08/03-broadcasting-and-ufunc","file":"03-broadcasting-and-ufunc.md","title":"03 · 广播与 ufunc","kind":"flow","secs":[{"h":"主题一：广播规则","s":"广播（broadcasting）是 NumPy 让不同形状的数组能做逐元素运算的机制。规则只有三条，从最右边的维度开始对齐：","c":{"lang":"python","code":"import numpy as np\na = np.arange(12).reshape(3, 4)\nb = np.array([10, 20, 30, 40])\nprint((a + b).shape)          # (3, 4)\nprint((a[:, :1] + b).shape)   # (3, 4) —— (3,1) 与 (4,) 广播\ntry:\n    a + np.array([1, 2, 3])\nexcept ValueError as e:\n    print(\"ValueError:\", str(e)[:60])"}},{"h":"主题二：axis 语义与聚合","s":"axis 是「沿哪个方向压下去」，不是「在第几个维度上操作」。对二维数组：","c":{"lang":"python","code":"import numpy as np\na = np.arange(12).reshape(3, 4)\nprint(a.sum(axis=0))   # [12 15 18 21] —— 4 个元素（按列）\nprint(a.sum(axis=1))   # [6 22 38]      —— 3 个元素（按行）\nprint(a.sum())         # 66"}}]},{"id":"py-ch08/04-pandas-series-dataframe-csv","file":"04-pandas-series-dataframe-csv.md","title":"04 · pandas：Series、DataFrame 与 CSV","kind":"stack","secs":[{"h":"主题一：Series / DataFrame 与索引对齐","s":"Series 是「带标签的一维数组」，DataFrame 是「共享同一行索引的 Series 字典」。核心差别在于：pandas 的运算默认按标签对齐，而不是按位置。","c":{"lang":"python","code":"import pandas as pd\ns1 = pd.Series([1, 2], index=[\"x\", \"y\"])\ns2 = pd.Series([10], index=[\"y\"])\nprint((s1 + s2).to_dict())   # {'x': nan, 'y': 12.0}"}},{"h":"主题二：读写 CSV 与分组聚合","s":"read_csv 是整章最常用的入口，几个必须掌握的参数：","c":{"lang":"python","code":"import pandas as pd\ntotal = 0\nfor chunk in pd.read_csv(\"big.csv\", chunksize=1000):\n    total += int(chunk[\"amount\"].sum())"}}]}],"exams":[{"kind":"choice","q":"np.array([1, 2, 3.5]) 的 dtype 是什么","stem":"np.array([1, 2, 3.5]) 得到的数组 dtype 是？","opts":[{"k":"A","t":"int64"},{"k":"B","t":"float64"},{"k":"C","t":"object"},{"k":"D","t":"float32"}],"ans":"B","why":"类型提升（type promotion）按「宽度与语义向上取齐」规则：int + float -> float、bool + int -> int。 若混入字符串，则退化为 <U.. 或 object，数值计算能力丧失：np.array([1, '2']).dtype 得到 <U21，里面存的是文本而不是数字。"},{"kind":"choice","q":"哪些索引方式返回的是副本而不是视图","stem":"下列哪种操作返回的结果与原数组不共享内存（即副本）？","opts":[{"k":"A","t":"a[1:3]（基本切片）"},{"k":"B","t":"a.reshape(2, 2)"},{"k":"C","t":"a.T（转置）"},{"k":"D","t":"a[[0, 2]]（花式索引）"}],"ans":"D","why":"判定标准是能否用「起始指针 + strides」表达结果： - 能 -> 视图：基本切片、reshape、ravel、transpose、broadcast_to - 不能 -> 副本：花式索引、布尔索引、astype（换 dtype）、copy()、算术运算结果 用 np.shares_memory(a, b) 可一行验证。这是排查「改了 b 为什么 a 也变了」类 bug…"},{"kind":"output","q":"写出 a.sum(axis=0) 的结果","stem":"python import numpy as np a = np.arange(6).reshape(2, 3) print(a.sum(axis=0)) print(a.sum(axis=1)) 两行输出分别是什么？","opts":[],"ans":"","why":"a 为 [[0,1,2],[3,4,5]]。 - axis=0 表示沿第 0 维（轴）推进，把该轴的多个元素压成 1 个 -> 结果 shape 为 (3,)，即每一列的和 [0+3, 1+4, 2+5] = [3,5,7]。 - axis=1 压掉第 1 维 -> 结果 shape 为 (2,)，即每一行的和 [0+1+2, 3+4+5] = [3,12]。 记忆口诀：「ax…"},{"kind":"fix_error","q":"修正形状不匹配的广播运算","stem":"下面代码报 operands could not be broadcast together，请指出原因并给出一种修法。 python x = np.ones((3, 4)) y = np.ones((3,)) print(x + y)","opts":[],"ans":"import numpy as np x = np.ones((3, 4)) y = np.ones((3,)) # 方案一：把 y 补成列向量 (3,1)，让 3 对齐第 0 维，1 广播到第 1 维 y_col = y.reshape(3, 1) print((x + y_col).shape) print((x…","why":"广播三步走： 1. 把两个形状右对齐； 2. 每一对维度要么相等，要么其中一个是 1（可拉伸），要么其中一个缺失（当作 1）； 3. 全部满足才可广播，否则抛 ValueError。 (3,4) 与 (3,) 右对齐后是 (3,4) vs (_,3) —— 4 与 3 冲突。把它变成 (3,1) 才能表达「每行加同一个数」；若不 reshape 而 y 恰好长度为 4，则语义会…"},{"kind":"choice","q":"loc 与 iloc 的切片端点差异","stem":"对于索引为 ['a','b','c','d','e'] 的 Series，s.loc['b':'d'] 与 s.iloc[1:4] 的元素个数分别是？","opts":[{"k":"A","t":"都是 3 个"},{"k":"B","t":"都是 4 个"},{"k":"C","t":"loc 3 个，iloc 4 个"},{"k":"D","t":"loc 2 个，iloc 3 个"}],"ans":"A","why":"这是 pandas 最经典的混淆点之一。 记住： | 索引器 | 依据 | 切片端点 | |---|---|---| | loc | 标签 | 闭区间（含右） | | iloc | 位置 | 左闭右开 | 数量「恰好相同」是数据巧合：当标签恰好等距且与位置错开 1 时才会出现。判断依据只能是标签还是位置，不能靠数量推断。 另外 loc 用于布尔/可调用对象时也不支持位置语义。"},{"kind":"coding","q":"用 NumPy 向量化实现 KNN 预测","stem":"给定训练集 X_train (n,d)、标签 y_train (n,) 与测试集 X_test (m,d)，用向量化方式（禁止 Python 循环）实现 k 近邻分类：先算 (m,n) 的距离矩阵，再取每行最小的 k 个下标做多数投票。","opts":[],"ans":"import numpy as np def knn_predict(X_train, y_train, X_test, k=3): # (m,n) 的平方距离矩阵，全靠广播与矩阵乘 d2 = (X_test 2).sum(axis=1)[:, None] + (X_train 2).sum(axis=1)[None,…","why":"要点复盘： 1. 距离矩阵展开：(m,1) 与 (1,n) 广播成 (m,n)，这一步把 O(m·n·d) 的循环压成一次 BLAS 矩阵乘。 2. 数值截断：展开式有浮点误差，平方距离可能算出 -1e-13，np.maximum(d2, 0) 兜底，否则后续 sqrt 会得到 nan。 3. top-k 用 argpartition：只需部分有序，平均 O(n) 而非 arg…"},{"kind":"coding","q":"向量化实现 Z-score 标准化与相关系数","stem":"给定 X (n,d)，实现 standardize 返回按列标准化的结果（均值 0、标准差 1），并实现 pearson(a, b) 计算两列的皮尔逊相关系数。要求全部用向量化运算。","opts":[],"ans":"import numpy as np def standardize(X): mu = X.mean(axis=0) # (d,) sd = X.std(axis=0) # (d,) 总体标准差（ddof=0） return (X - mu) / sd def pearson(a, b): a = a - a.mean…","why":"关键点： - axis=0 而不是 axis=1：要对每一列（每个特征）做标准化，所以统计量必须沿行方向聚合。写成 axis=1 会把样本内标准化，语义完全错。 - std 默认 ddof=0（总体）：numpy 用总体标准差、pandas 的 Series.std() 用样本标准差（ddof=1），两者数值不同，是跨库复现实验时的常见偏差来源。 - 相关系数 = 标准化后点积…"},{"kind":"coding","q":"用 pandas 完成分组 TOP-N 与透视","stem":"给定订单表（city, product, amount），用 pandas 完成：① 每个城市金额最高的 2 个商品（TOP-N per group）；② 城市 × 商品的金额透视表；③ 计算每个城市的金额占比。要求用 groupby/pivot_table 完成，不做逐行循环。","opts":[],"ans":"import pandas as pd df = pd.DataFrame({ 'city': ['BJ', 'BJ', 'BJ', 'SH', 'SH', 'SH', 'GZ', 'GZ'], 'product': ['A', 'B', 'C', 'A', 'B', 'C', 'A', 'B'], 'amount':…","why":"要点： 1. TOP-N per group 的正确顺序是先排序再 head，不是 groupby.apply(lambda g: g.nlargest(...)) —— 前者是向量化的，后者每组建一次 Python 调用，规模大时慢一个量级。 2. transform('sum') 与 agg('sum') 的区别：agg 把每组压成一行，transform 把组内聚合值广播…"}],"works":[{"h":"把切片当副本改","d":"sub = a[1:3]; sub[0] = 9 会改到原数组 a，因为基本切片是视图。要独立改就 sub = a[1:3].copy()。"},{"h":"把花式索引当视图改","d":"a[[1, 2]][0] = 9 改的是副本，原数组不变，且不报错。赋值必须落回原数组：a[1] = 9。"},{"h":"用 and / or 连接布尔条件","d":"a > 0 and a < 5 会对数组做真值测试并抛 ValueError。正确写法 (a > 0) & (a < 5)，两个条件都要加括号。"},{"h":"忘记 keepdims 导致广播失败","d":"a a.mean(axis=1) 形状是 (3,4) 与 (3,)，直接报错。改成 a a.mean(axis=1, keepdims=True)。"},{"h":"广播前不估内存","d":"x[:, None] x[None, :] 在 len(x)=100000 时要 10^10 个元素，直接 OOM。大形状先算元素数，必要时分块。"},{"h":"reshape 一定返回视图的误判","d":"转置后内存不连续，a.T.reshape(-1) 会静默拷贝。用 np.shares_memory 或看 arr.base 实证。"},{"h":"np.ptp(a) 与 a.ptp() 混用","d":"NumPy 2.0 起已移除 ndarray.ptp() 方法，只能写函数形式 np.ptp(a)，老代码必须改。"},{"h":"NaN 的传播与跳过混为一谈","d":"np.mean([1, nan, 3]) 返回 nan（传播）；pandas 的 df.mean() 默认跳过 NaN。跨库换用时结果不同，务必显式 np.nanmean。"}],"asks":[{"q":"NumPy 里视图（view）和副本（copy）怎么区分？实际排查时有什么价值？","a":"区分标准：结果能否用「起始指针 + strides」表达。能就是视图（基本切片、reshape、ravel、transpose、broadcast_to），不能就是副本（花式索引、布尔索引、astype、copy()、任何算术运算）。 一行验证：np.shares_memory(a, b)。 排查价值：这类差异导致两类典型 bug —— 1. 「我明明只改了子数组，原数组怎么变了」：你拿到的是视图…","fu":["a.reshape(-1) 和 a.ravel() 有什么区别？","转置后的数组 C_CONTIGUOUS 是 True 还是 False？"],"tag":"字节跳动/美团"},{"q":"广播规则的完整判定流程是什么？举一个看起来能对齐、实际会静默出错的例子。","a":"判定流程： 1. 两形状右对齐； 2. 逐对维度：相等 -> 通过；一个是 1 -> 可拉伸；一个缺失 -> 当作 1； 3. 全部通过才可广播，否则 ValueError。结果 shape 取每一对的最大值。 静默出错的典型：想「每个样本减去自身均值」写成 python X - X.mean(axis=1) # X 是 (n, d)，mean(axis=1) 是 (n,) (n,d) 与 (n,…","fu":["np.broadcast_shapes 能做什么？","np.broadcast_to 返回的数组可以写吗？"],"tag":"阿里云/腾讯"},{"q":"axis=0 和 axis=1 到底压掉哪一维？怎么一眼看准？","a":"规则：axis=n 表示「消掉第 n 维」，结果 shape 等于原 shape 去掉第 n 项。 - 二维 (2,3)：sum(axis=0) 消掉行 -> (3,)，是每一列的和；sum(axis=1) 消掉列 -> (2,)，是每一行的和。 - 三维 (2,3,4)：sum(axis=1) 得 (2,4)；sum(axis=(0,2)) 得 (3,)。 易错点：口语里说「对行求和」有歧义 —…","fu":["argmax(axis=0) 返回的是什么？","np.concatenate 的 axis 与聚合的 axis 语义一样吗？"],"tag":"美团/京东"},{"q":"pandas 的「索引对齐」是什么？它带来的最大陷阱是什么？","a":"机制：两个 Series/DataFrame 做算术或合并时，pandas 按标签（label）对齐，而不是按位置。只要参与运算的任一方带索引，就先取索引并集、各自按标签取值，缺的位置填 NaN。 最大陷阱： 1. 静默改变 dtype：int + int 一旦出现缺失位置就升为 float64，整数键变成 1.0，下游 join 可能因此对不上。 2. 误以为按位置相加：s1 + s2 与 s1…","fu":["reset_index(drop=True) 什么时候必须加？","索引有重复时相加会发生什么？"],"tag":"蚂蚁集团/字节跳动"}]},{"id":"py-ch09","subj":"python","title":"面向对象：类、继承与魔术方法","summary":"Python 的类是「带描述符协议的名字空间」，不是 Java 那种编译期定型的东西。本章讲清：实例字典与类字典的查找顺序、__init__ 与 __new__ 的分工、继承与方法解析顺序（MRO）与 super()、魔术方法如何让对象接入…","concepts":[{"id":"py-ch09/01-class-namespace-and-lookup","file":"01-class-namespace-and-lookup.md","title":"类、实例与属性查找顺序","kind":"flow","secs":[{"h":"可变类属性是共享的","s":"这不是 bug，是「类属性只有一个」。需要每实例一份时，在 __init__ 里赋值。","c":{"lang":"python","code":"class Bad:\n    tags = []                    # 类属性，所有实例共享同一个 list\n\na, b = Bad(), Bad()\na.tags.append(\"x\")\nprint(b.tags)                    # ['x']  —— b 也被改了"}},{"h":"__init__ 不负责创建对象","s":"很多人以为 __init__ 是构造函数。实际分工是：","c":{"lang":"python","code":"class Probe:\n    def __new__(cls):\n        print(\"1. __new__ 被调用\")\n        return super().__new__(cls)\n    def __init__(self):\n        print(\"2. __init__ 被调用\")\n\np = Probe()\n# 1. __new__ 被调用\n…"}}]},{"id":"py-ch09/02-inheritance-mro-super","file":"02-inheritance-mro-super.md","title":"继承、MRO 与 super()","kind":"flow","secs":[{"h":"super() 不是「父类」","s":"这是最深的误解。super() 返回的是「MRO 上当前类的下一个类」，不一定是父类：","c":{"lang":"python","code":"class Base:\n    def __init__(self):\n        print(\"Base\")\nclass A(Base):\n    def __init__(self):\n        print(\"A\"); super().__init__()\nclass B(Base):\n    def __init__(self):\n        print(\"B\"); super().__init__()\n…"}},{"h":"什么时候真的该用多继承","s":"大多数情况下不该。Python 界的共识是：","c":{"lang":"python","code":"class A: pass\nclass B(A): pass\nclass C(A): pass\nclass D(B, C): pass\n\nprint([c.__name__ for c in D.__mro__])"}}]},{"id":"py-ch09/03-dunder-protocols","file":"03-dunder-protocols.md","title":"魔术方法：让对象接入语言协议","kind":"flow","secs":[{"h":"三个必须知道的规矩","s":"Python 认为「相等的对象应该 hash 相同」，你改了相等语义就默认你不能被 hash（否则会破坏 dict 的","c":null},{"h":"@property 与三种方法修饰符","s":"判据：需要访问实例状态用普通方法；需要创建实例（工厂）或访问类属性用 classmethod；","c":{"lang":"python","code":"class Circle:\n    def __init__(self, r):\n        self._r = r\n\n    @property\n    def area(self):                 # 调用时不用写 ()：c.area\n        return 3.14159 * self._r ** 2\n\n    @area.setter\n…"}},{"h":"魔术方法查找为什么绕过实例字典","s":"这是 Python 对象模型里最反直觉的一条规则，理解了它就能解释一批「明明写了却不生效」的现象：","c":{"lang":"python","code":"class Sneaky:\n    def __len__(self):\n        return 3\n\ns = Sneaky()\ns.__len__ = lambda: 99          # 往实例上塞一个同名方法\nprint(len(s))                    # 3，不是 99\nprint(s.__len__())               # 99，直接调用才走实例字典"}}]},{"id":"py-ch09/04-oop-practical-recipes","file":"04-oop-practical-recipes.md","title":"Python 面向对象实战手记：凯喵的十二次「属性找不到，但代码没写错」","kind":"flow","secs":[{"h":"开场：属性查找不是「读字段」，是「走一条搜索链」","s":"写 obj.x 时，Python 不是简单地从 obj.__dict__ 里取。它走一条明确的链路：先查类型上定义了 __getattribute__ 吗（几乎所有类都有默认实现），然后按「数据描述符 → 实例字典 → 非数据描述符 →…","c":{"lang":"python","code":"class A:\n    x = \"class-attr\"\n\na = A()\nprint(a.x)              # \"class-attr\"（从类上找到）\na.x = \"inst-attr\"       # 写进实例字典\nprint(a.x)              # \"inst-attr\"（实例字典优先）\nprint(A.x)              # \"class-attr\"（类属性不变）"}},{"h":"收尾：Python OOP 的三层理解","s":"凯喵最后总结：Python 的面向对象可以分三层理解。","c":null}]}],"exams":[{"kind":"output","q":"读代码写输出（实例属性遮蔽类属性）","stem":"python class Cat: sound = \"meow\" c = Cat() print(c.sound) c.sound = \"nya\" print(Cat.sound, c.sound) print(\"sound\" in vars(c), \"sound\" in vars(Cat))","opts":[],"ans":"meow meow nya True True","why":"第一行从类字典取到 meow。c.sound = \"nya\" 在实例字典里新建一项，不修改类属性，所以第二行打印 meow nya。第三行用 vars() 看字典内容：实例字典里现在有 sound（True），类字典里本来就有（True）——两者并存，实例遮蔽类。"},{"kind":"choice","q":"关于 super()，正确的是","stem":"在 class D(B, C) 的 B 的方法里调用 super()，它会去找","opts":[{"k":"A","t":"B 的所有直接父类，按定义顺序依次调用"},{"k":"B","t":"B 的父类 object"},{"k":"C","t":"type(self).__mro__ 中 B 之后的下一个类，可能是 C"},{"k":"D","t":"总是 B 自己，形成递归"}],"ans":"C","why":"无参 super() 的查找起点是「当前类在实例实际 MRO 中的位置之后」，因此 D 的实例走 B 时，下一个是 C 而不是 B 的父类。这正是协作式多继承能工作（也要求链上每个类都调用 super()）的原因。"},{"kind":"fix","q":"改错：为什么这个 set 查不到刚放进去的元素","stem":"下面的代码在 s.add(p) 之后 p in s 返回 False。找出原因并修正。 python class Point: def __init__(self, x, y): self.x, self.y = x, y def __eq__(self, other): return self.x == other.x and self.y == other.y p = Point(1, 2)…","opts":[],"ans":"class Point: __slots__ = (\"x\", \"y\") def __init__(self, x, y): self.x, self.y = x, y def __eq__(self, other): if not isinstance(other, Point): return NotImplemen…","why":"定义 __eq__ 时 Python 自动把 __hash__ 置为 None，对象不可 hash。原代码能建出 set 说明 __hash__ 未被定义时的默认 id 版 hash 仍生效——两个不同实例 hash 不同，set 用 hash 定位，因此 p in s 为 False，而 p == Point(1,2) 因为走了 __eq__ 为 True。修法：显式实现 _…"},{"kind":"choice","q":"classmethod 与 staticmethod","stem":"需要一个「根据参数创建实例」的工厂方法，并希望子类调用时创建的是子类实例。应该用","opts":[{"k":"A","t":"@staticmethod，因为它不依赖实例"},{"k":"B","t":"@classmethod，第一个参数 cls 保证子类调用时绑定到子类"},{"k":"C","t":"普通实例方法，在外部先 __new__ 一个空对象"},{"k":"D","t":"@property，把构造逻辑包装成属性"}],"ans":"B","why":"classmethod 的第一个参数是类本身，子类调用时 cls 就是子类，所以工厂里写 return cls(...) 能自动产出正确的子类实例。staticmethod 拿不到类，只能硬编码基类名，子类调用会返回基类实例——这是工厂方法最常见的隐蔽 bug。"},{"kind":"coding","q":"实现一个可迭代、可 len、可 in 的 Playlist","stem":"实现 Playlist 类：构造时接受任意可迭代对象并拷贝一份；支持 len(pl)、for x in pl、x in pl、pl[0]、切片 pl[1:3]；repr() 输出形如 Playlist(['a', 'b'])；两个 Playlist 内容相同时 == 为 True。要求写出 __len__、__iter__、__contains__、__getitem__、__repr__、__e…","opts":[],"ans":"class Playlist: def __init__(self, songs): self._songs = list(songs) def __len__(self): return len(self._songs) def __iter__(self): return iter(self._songs) def…","why":"要点：① __init__ 里 list(songs) 拷贝一份，避免外部列表后续变化影响对象，也允许传入生成器；② __iter__ 返回 iter(...) 而不是 self，避免对象自身状态污染迭代；③ __getitem__ 既支持下标也支持切片（list 的切片自然返回 list）；④ __eq__ 先返回 NotImplemented 再比较，保证对称性；⑤ __r…"},{"kind":"coding","q":"用 ABC + mixin 实现一个带序列化能力的容器","stem":"实现 JsonMixin（提供 to_json()，用标准库 json.dumps 序列化 self._items）与 Bag（继承 JsonMixin 与 collections.abc.MutableSequence，内部用 list 存储，实现 __getitem__/__setitem__/__delitem__/__len__/insert）。要求：不重复写 __iter__/__con…","opts":[],"ans":"import json from collections.abc import MutableSequence class JsonMixin: def to_json(self): return json.dumps(self._items, ensure_ascii=False) class Bag(JsonMix…","why":"MutableSequence 只要求实现五个方法（__getitem__/__setitem__/__delitem__/__len__/insert），其余 append/extend/pop/remove/__iter__/__contains__/index/count/reverse 由 ABC 通过 mixin 方法自动提供——这正是「继承 ABC 而不是手写容器」…"},{"kind":"output","q":"读代码写输出（类属性共享）","stem":"python class Box: items = [] def add(self, x): self.items.append(x) a, b = Box(), Box() a.add(1) b.add(2) print(a.items, b.items) print(a.items is b.items)","opts":[],"ans":"[1, 2] [1, 2] True","why":"items = [] 是类属性，定义时求值一次，a 与 b 都没有自己的 items，self.items.append(...) 解析到同一个 list 并原地修改。所以两次 append 都落在同一个列表里，两个实例看到 [1, 2]，且 is 判断为同一个对象。修法是在 __init__ 里 self.items = []。"}],"works":[{"h":"可变默认参数 / 可变类属性","d":"错在：class Foo: items = [] 或 def f(x, acc=[])，然后往里 append。 为什么：类属性与函数默认值都在定义时只求值一次，所有实例/所有调用共享同一个对象。表现出来就是「第二次调用时里面还有上次的数据」，而这在单元测试里常常因为用例顺序不同而时好时坏。"},{"h":"super() 用错对象","d":"错在：多继承链里写成 Base.__init__(self) 直接调父类，或者子类 __init__ 忘了调 super()。 为什么：直接点名父类会绕过 MRO，导致链上其他 mixin 的初始化被跳过；忘了调用则父类状态根本没初始化，属性访问时 AttributeError。在多继承里这两种错都不会在定义时报，只在运行时某个路径上…"},{"h":"__eq__ 返回 False 而不是 NotImplemented","d":"错在：def __eq__(self, other): return self.x == other.x，没有先判断类型。 为什么：传入不同类型时 other.x 可能不存在（AttributeError），或者返回 False 阻断了对方更精确的比较。表现为 a == b 与 b == a 结果不一致，或者排序/去重出现莫名其妙的错…"},{"h":"重写 __eq__ 后忘了 __hash__","d":"错在：定义了 __eq__，然后把对象放进 set 或当 dict 键，发现「明明放进去了却取不到」。 为什么：定义 __eq__ 时 Python 自动把 __hash__ 设为 None，对象变成不可 hash，set 会直接抛 TypeError: unhashable type。更隐蔽的情况是手动实现了一个错误的 __hash…"},{"h":"以为重写 __new__ 返回什么就得到什么","d":"错在：def __new__(cls): return 42，期望 Obj() 得到 42，但后续 obj.attr 全部失败。 为什么：__new__ 返回非本类实例时，__init__ 不会被调用；而且返回的对象类型就是 int，没有你定义的任何属性。「单例」写法里如果缓存对象写错，会出现「第二次拿到的是个半初始化对象」。这条规则…"},{"h":"往实例上挂魔术方法，期望生效","d":"错在：obj.__len__ = lambda: 5，然后 len(obj) 还是旧值。 为什么：解释器对特殊方法走 type(obj).__len__(obj)，在类型层面查找，显式跳过实例字典。普通方法能被实例属性遮蔽，魔术方法不能。这条规则导致「同一个 mock 技巧有的生效有的不生效」——普通方法打实例有效，魔术方法必须打类。"},{"h":"isinstance 判父类时用 type() ==","d":"错在：if type(x) == Animal: 来判断「是不是动物」。 为什么：type() 返回精确类型，子类实例一律不通过，于是 Dog(Animal) 被判定为「不是动物」。反过来，用 type(x) == Animal 做分发时，任何子类都会走到「都不匹配」的分支，表现为「新增子类后功能静默失效」——不报错，只是没生效。"},{"h":"@property 上写 @staticmethod 或顺序写反","d":"错在：@staticmethod 套在 @property 外面，或者 @property 与 @x.setter 名字不一致。 为什么：装饰器顺序决定最终对象类型——@property 必须是最外层（最靠近函数的是 @staticmethod 就先变成静态方法，再包成 property 行为不对）。setter 名字不一致（@y.s…"}],"asks":[{"q":"Python 的属性和方法查找顺序是怎样的？描述符协议在哪一步生效？","a":"先查类型（及其 MRO）上是否存在数据描述符（定义了 __set__/__delete__ 的，如 property），有则直接用它；否则查实例 __dict__；再否则查类型上的非数据描述符（普通函数、classmethod）或普通类属性；都没有再走 __getattr__。这条不对称规则解释了「方法能被实例属性遮蔽，property 不能」。","fu":["为什么 property 不能被实例字典遮蔽，而普通方法可以？","__getattr__ 与 __getattribute__ 的调用时机有什么区别？"],"tag":"通用"},{"q":"多继承的 MRO 是怎么算的？super() 到底做了什么？","a":"MRO 用 C3 线性化：保证子类先于父类、父类间保持声明顺序、每个类只出现一次，无法满足时抛 TypeError。super() 不是「父类」，它返回一个代理，从「当前类在 type(self).__mro__ 中的下一个位置」开始查找。所以 class D(B, C) 中 B 里的 super() 会找到 C。这也是协作式多继承要求链上每个类都调用 super().__init__(kwarg…","fu":["C3 线性化为什么比深度优先更合理？举个它会报错的例子。","mixin 为什么不应该定义 __init__ 状态？"],"tag":"通用"},{"q":"为什么定义了 __eq__ 之后对象就不能当 dict 的键了？怎么正确实现？","a":"因为 Python 认为「相等的对象 hash 必须相同」，改写了相等语义就等于放弃了默认的 id-based hash，所以自动把 __hash__ 置为 None（不可 hash）。正确实现要满足两条：① __hash__ 使用的字段是 __eq__ 比较字段的子集；② 这些字段不可变。最简单的方式是 @dataclass(frozen=True)，它会自动生成满足契约的一对。","fu":["如果对象包含 list 字段又想可 hash，怎么办？","__hash__ 返回常量行不行？会有什么性能后果？"],"tag":"通用"},{"q":"__new__ 和 __init__ 有什么区别？什么时候必须用 __new__？","a":"__new__ 负责创建并返回实例（类方法，第一参数是 cls），__init__ 负责初始化已存在的实例且必须返回 None。日常业务只写 __init__。必须用 __new__ 的场景：① 单例/受控实例数量；② 继承不可变类型（int/str/tuple）想改构造语义，因为它们的值在 __new__ 里就固定了，__init__ 改不了；③ 需要根据参数返回不同类的实例（工厂）。","fu":["为什么不可变类型的子类不能只重写 __init__？","__new__ 里返回一个别的类的实例会发生什么？"],"tag":"通用"}]}];

export default CHAPTERS;
